import re


class SQLError(Exception):
    pass


TOK = re.compile(r"\s*(?:(\d+)|'((?:[^']|'')*)'|([A-Za-z_][A-Za-z_0-9]*)|(\|\||<=|>=|<>|!=|[-+*/%(),;<>=]))")


def lex(sql):
    toks = []
    pos = 0
    sql = sql.rstrip()
    while pos < len(sql):
        m = TOK.match(sql, pos)
        if not m:
            raise SQLError(f"syntax error near {sql[pos:pos + 10]!r}")
        pos = m.end()
        n, s, w, o = m.groups()
        if n is not None:
            toks.append(('num', int(n)))
        elif s is not None:
            toks.append(('str', s.replace("''", "'")))
        elif w is not None:
            toks.append(('word', w))
        else:
            toks.append(('op', o))
    toks.append(('eof', None))
    return toks


FUNCS = {'UPPER': (1, 1), 'LOWER': (1, 1), 'LENGTH': (1, 1), 'ABS': (1, 1),
         'SUBSTR': (2, 3), 'COALESCE': (1, 99), 'NULLIF': (2, 2)}


class Parser:
    def __init__(self, sql):
        self.t = lex(sql)
        self.i = 0

    def peek(self):
        return self.t[self.i]

    def kw(self, *names, k=0):
        t = self.t[self.i + k]
        return t[0] == 'word' and t[1].upper() in names

    def op(self, o):
        t = self.t[self.i]
        return t[0] == 'op' and t[1] == o

    def take(self):
        t = self.t[self.i]
        self.i += 1
        return t

    def expect_kw(self, name):
        if not self.kw(name):
            raise SQLError(f"expected {name}")
        self.i += 1

    def expect_op(self, o):
        if not self.op(o):
            raise SQLError(f"expected {o!r}")
        self.i += 1

    def name(self):
        t = self.take()
        if t[0] != 'word':
            raise SQLError("syntax error")
        return t[1]

