    def postfix(self, e, neg):
        w = self.take()[1].upper()
        if w == 'BETWEEN':
            lo = self.add()
            self.expect_kw('AND')
            return ('between', neg, e, lo, self.add())
        if w == 'LIKE':
            return ('like', neg, e, self.add())
        self.expect_op('(')
        items = [self.expr()]
        while self.op(','):
            self.i += 1
            items.append(self.expr())
        self.expect_op(')')
        return ('in', neg, e, items)

    def add(self):
        e = self.mul()
        while self.op('+') or self.op('-'):
            o = self.take()[1]
            e = ('bin', o, e, self.mul())
        return e

    def mul(self):
        e = self.concat()
        while self.op('*') or self.op('/') or self.op('%'):
            o = self.take()[1]
            e = ('bin', o, e, self.concat())
        return e

    def concat(self):
        e = self.unary()
        while self.op('||'):
            self.i += 1
            e = ('concat', e, self.unary())
        return e

    def unary(self):
        if self.op('-'):
            self.i += 1
            return ('neg', self.unary())
        if self.op('+'):
            self.i += 1
            return self.unary()
        return self.primary()

