    def primary(self):
        t = self.take()
        if t[0] in ('num', 'str'):
            return ('lit', t[1])
        if t[0] == 'op' and t[1] == '(':
            e = self.expr()
            self.expect_op(')')
            return e
        if t[0] == 'word':
            w = t[1].upper()
            if w == 'NULL':
                return ('lit', None)
            if w == 'CASE':
                return self.case()
            if self.op('('):
                return self.call(w)
            raise SQLError(f"no such column: {t[1]}")
        raise SQLError("syntax error")

    def case(self):
        base = None
        if not self.kw('WHEN'):
            base = self.expr()
        whens = []
        while self.kw('WHEN'):
            self.i += 1
            c = self.expr()
            self.expect_kw('THEN')
            whens.append((c, self.expr()))
        els = None
        if self.kw('ELSE'):
            self.i += 1
            els = self.expr()
        self.expect_kw('END')
        if not whens:
            raise SQLError("syntax error")
        return ('case', base, whens, els)

