    def call(self, name):
        self.i += 1
        args = []
        if not self.op(')'):
            args.append(self.expr())
            while self.op(','):
                self.i += 1
                args.append(self.expr())
        self.expect_op(')')
        if name not in FUNCS:
            raise SQLError(f"no such function: {name}")
        lo, hi = FUNCS[name]
        if not lo <= len(args) <= hi:
            raise SQLError(f"wrong number of arguments to {name}")
        return ('call', name, args)


def to_num(v):
    if v is None or isinstance(v, int):
        return v
    m = re.match(r"\s*[-+]?\d+", v)
    return int(m.group()) if m else 0


def to_text(v):
    return None if v is None else str(v)


def t3(v):
    return None if v is None else int(to_num(v) != 0)


def and3(a, b):
    if a == 0 or b == 0:
        return 0
    if a is None or b is None:
        return None
    return 1


def or3(a, b):
    if a == 1 or b == 1:
        return 1
    if a is None or b is None:
        return None
    return 0


def not3(a):
    return None if a is None else 1 - a


def cmp_vals(a, b):
    ka = (0, a) if isinstance(a, int) else (1, a)
    kb = (0, b) if isinstance(b, int) else (1, b)
    return (ka > kb) - (ka < kb)

