def arith(op, a, b):
    a, b = to_num(a), to_num(b)
    if a is None or b is None:
        return None
    if op == '+':
        return a + b
    if op == '-':
        return a - b
    if op == '*':
        return a * b
    if b == 0:
        return None
    if op == '/':
        q = abs(a) // abs(b)
        return -q if (a < 0) != (b < 0) else q
    r = abs(a) % abs(b)
    return -r if a < 0 else r


def like_re(p):
    out = []
    for ch in p:
        out.append('.*' if ch == '%' else '.' if ch == '_' else re.escape(ch))
    return re.compile(''.join(out), re.S | re.I)


def substr(s, start, length=None):
    n = len(s)
    if start < 0:
        start = n + start + 1
    if length is None:
        lo, hi = start, n + 1
    elif length >= 0:
        lo, hi = start, start + length
    else:
        lo, hi = start + length, start
    lo = max(lo, 1)
    hi = min(hi, n + 1)
    return s[lo - 1:hi - 1] if lo < hi else ''

