def cmp3(op, a, b):
    if a is None or b is None:
        return None
    c = cmp_vals(a, b)
    return int({'=': c == 0, '!=': c != 0, '<>': c != 0, '<': c < 0,
                '<=': c <= 0, '>': c > 0, '>=': c >= 0}[op])


def call_fn(name, args):
    if name == 'COALESCE':
        for a in args:
            v = ev(a)
            if v is not None:
                return v
        return None
    if name == 'NULLIF':
        a, b = ev(args[0]), ev(args[1])
        if a is None or (b is not None and cmp_vals(a, b) == 0):
            return None
        return a
    v = ev(args[0])
    if v is None:
        return None
    if name == 'UPPER':
        return to_text(v).upper()
    if name == 'LOWER':
        return to_text(v).lower()
    if name == 'LENGTH':
        return len(to_text(v))
    if name == 'ABS':
        return abs(to_num(v))
    start = to_num(ev(args[1]))
    length = to_num(ev(args[2])) if len(args) > 2 else None
    if start is None or (len(args) > 2 and length is None):
        return None
    return substr(to_text(v), start, length)

