def ev(n):
    k = n[0]
    if k == 'lit':
        return n[1]
    if k == 'neg':
        v = to_num(ev(n[1]))
        return None if v is None else -v
    if k == 'bin':
        return arith(n[1], ev(n[2]), ev(n[3]))
    if k == 'concat':
        a, b = ev(n[1]), ev(n[2])
        return None if a is None or b is None else to_text(a) + to_text(b)
    if k == 'cmp':
        return cmp3(n[1], ev(n[2]), ev(n[3]))
    if k == 'and':
        return and3(t3(ev(n[1])), t3(ev(n[2])))
    if k == 'or':
        return or3(t3(ev(n[1])), t3(ev(n[2])))
    if k == 'not':
        return not3(t3(ev(n[1])))
    if k == 'is':
        a, b = ev(n[2]), ev(n[3])
        if a is None or b is None:
            same = a is None and b is None
        else:
            same = cmp_vals(a, b) == 0
        return int(same != bool(n[1]))
    if k == 'between':
        x = ev(n[2])
        r = and3(cmp3('>=', x, ev(n[3])), cmp3('<=', x, ev(n[4])))
        return not3(r) if n[1] else r
    if k == 'like':
        x, p = ev(n[2]), ev(n[3])
        if x is None or p is None:
            return None
        r = int(bool(like_re(to_text(p)).fullmatch(to_text(x))))
        return 1 - r if n[1] else r
    if k == 'in':
        x = ev(n[2])
        vals = [ev(i) for i in n[3]]
        if x is None:
            r = None
        elif any(v is not None and cmp_vals(x, v) == 0 for v in vals):
            r = 1
        elif any(v is None for v in vals):
            r = None
        else:
            r = 0
        return not3(r) if n[1] else r
    if k == 'case':
        return ev_case(n)
    return call_fn(n[1], n[2])


def ev_case(n):
    _, base, whens, els = n
    if base is None:
        for c, v in whens:
            if t3(ev(c)) == 1:
                return ev(v)
    else:
        x = ev(base)
        for c, v in whens:
            y = ev(c)
            if x is not None and y is not None and cmp_vals(x, y) == 0:
                return ev(v)
    return None if els is None else ev(els)


def run(sql):
    return [tuple(ev(e) for e in Parser(sql).query())]
