def resolve_term(e, sel):
    if e[0] == 'lit' and isinstance(e[1], int) and not isinstance(e[1], bool):
        if not 1 <= e[1] <= len(sel):
            raise SQLError("ORDER BY term out of range")
        return ('out', e[1] - 1)
    if e[0] == 'col' and e[1] is None:
        for i, (_, alias) in enumerate(sel):
            if alias is not None and alias.lower() == e[2].lower():
                return ('out', i)
    return ('expr', e)


def execute(sql, tables):
    distinct, items, table, alias, where, terms, lim, off = SelectParser(sql).query()
    if table is None:
        envs, binding, cols = [NoEnv()], None, []
    else:
        name, cols_rows = table, find_table(tables, table)
        cols, rows = list(cols_rows[0]), cols_rows[1]
        binding = alias or name
        envs = [RowEnv(binding, cols, r) for r in rows]
    sel = expand(items, table, binding, cols)
