        for out, keys in out_rows:
            if out not in seen:
                seen.add(out)
                kept.append((out, keys))
        out_rows = kept
    for idx in reversed(range(len(terms))):
        out_rows.sort(key=lambda r: sort_key(r[1][idx]), reverse=terms[idx][1])
