        q = abs(a) // abs(b)
        if o == "/":
            return q if (a < 0) == (b < 0) else -q
        return a - b * (q if (a < 0) == (b < 0) else -q)
    if t == "cmp":
        a, b = ev(n[2], row), ev(n[3], row)
        if a is None or b is None:
            return None
        a, b = sortkey(a), sortkey(b)
        return int({"=": a == b, "!=": a != b, "<>": a != b, "<": a < b,
                    "<=": a <= b, ">": a > b, ">=": a >= b}[n[1]])
    if t == "and":
        a = truth(ev(n[1], row))
        if a == 0:
            return 0
        b = truth(ev(n[2], row))
        if b == 0:
            return 0
        return None if a is None or b is None else 1
    if t == "or":
        a = truth(ev(n[1], row))
        if a == 1:
            return 1
        b = truth(ev(n[2], row))
        if b == 1:
            return 1
        return None if a is None or b is None else 0
    if t == "not":
        a = truth(ev(n[1], row))
        return None if a is None else 1 - a
    if t == "isnull":
        r = ev(n[1], row) is None
        return int(r != n[2])
    if t == "in":
        x = ev(n[1], row)
        if x is None:
            return None
        res, saw = 0, False
        for it in n[2]:
            v = ev(it, row)
            if v is None:
                saw = True
            elif sortkey(v) == sortkey(x):
                res = 1
                break
        if res == 0 and saw:
            return None
        return 1 - res if n[3] else res
    if t == "like":
        a, p = ev(n[1], row), ev(n[2], row)
        if a is None or p is None:
            return None
        r = like(to_text(a), to_text(p))
        return int(r != n[3])
    if t == "between":
        x, lo, hi = ev(n[1], row), ev(n[2], row), ev(n[3], row)
        parts = []
        for ok in ((None if x is None or lo is None else sortkey(x) >= sortkey(lo)),
                   (None if x is None or hi is None else sortkey(x) <= sortkey(hi))):
            parts.append(ok)
        if False in parts:
            r = 0
        elif None in parts:
            return None
        else:
            r = 1
        return 1 - r if n[4] else r
    if t == "case":
        if n[1] is None:
            for c, v in n[2]:
                if truth(ev(c, row)) == 1:
                    return ev(v, row)
        else:
            x = ev(n[1], row)
            for c, v in n[2]:
                w = ev(c, row)
                if x is not None and w is not None and sortkey(x) == sortkey(w):
                    return ev(v, row)
        return ev(n[3], row) if n[3] is not None else None
    if t == "func":
        return func(n[1], [lambda a=a: ev(a, row) for a in n[2]])
    raise ValueError("cannot evaluate %r" % (n,))


def func(name, args):
    if name == "COALESCE":
        for a in args:
            v = a()
            if v is not None:
                return v
        return None
    vals = [a() for a in args]
    if name == "NULLIF":
        a, b = vals
        return None if a is not None and b is not None and sortkey(a) == sortkey(b) else a
    if not vals:
        raise ValueError("bad call to " + name)
    v = vals[0]
    if v is None:
        return None
    if name == "UPPER":
        return to_text(v).upper()
    if name == "LOWER":
        return to_text(v).lower()
    if name == "LENGTH":
        return len(to_text(v))
    if name == "ABS":
        return abs(to_num(v))
    if name == "SUBSTR":
        s = to_text(v)
        if len(vals) < 2 or vals[1] is None:
            return None
        start = to_num(vals[1])
        if len(vals) > 2:
            if vals[2] is None:
                return None
            ln = to_num(vals[2])
            if ln < 0:
                end, start = start, start + ln
                end = end
                lo, hi = start, end
            else:
                lo, hi = start, start + ln
        else:
            lo, hi = start, len(s) + 1
        if start == 0 and len(vals) <= 2:
            lo = 1
        lo, hi = max(lo, 1), min(hi, len(s) + 1)
        return s[lo - 1:hi - 1] if hi > lo else ""
    raise ValueError("no such function: " + name)


