        l = self.unary()
        while self.op("||"):
            self.i += 1
            l = ("bin", "||", l, self.unary())
        return l

    def unary(self):
        if self.op("-"):
            self.i += 1
            return ("neg", self.unary())
        if self.op("+"):
            self.i += 1
            return self.unary()
        return self.primary()

    def primary(self):
        k, v = self.next()
        if k in ("num", "str"):
            return ("lit", v)
        if k == "op" and v == "(":
            e = self.expr()
            self.expect_op(")")
            return e
        if k == "id":
            u = v.upper()
            if u == "NULL":
                return ("lit", None)
            if u == "CASE":
                return self.case()
            if self.op("("):
                self.i += 1
                args = []
                if not self.op(")"):
                    args.append(self.expr())
                    while self.op(","):
                        self.i += 1
                        args.append(self.expr())
                self.expect_op(")")
                return ("func", u, args)
            return ("col", v)
        raise ValueError("syntax error")

    def case(self):
        operand = None
        if not self.kw("WHEN"):
            operand = self.expr()
        whens, els = [], None
        while self.kw("WHEN"):
            self.i += 1
            c = self.expr()
            self.expect_kw("THEN")
            whens.append((c, self.expr()))
        if self.kw("ELSE"):
            self.i += 1
            els = self.expr()
        self.expect_kw("END")
        return ("case", operand, whens, els)
