from .evaluator import ev
from .values import AMBIG, truth


def load(tables, ref, outer):
    from .engine import execute
    name, alias = ref
    al = alias.lower()
    if isinstance(name, dict):
        cols, rows = execute(name, {"__tables__": tables})
    else:
        cols, rows = tables[name.lower()]
    pairs = [(al, c) for c in cols]
    envs = [{al + "." + c.lower(): v for c, v in zip(cols, r)} for r in rows]
    return pairs, envs


def finish(env, cols):
    out = dict(env)
    for al, c in cols:
        k = c.lower()
        out[k] = AMBIG if k in out else env[al + "." + k]
    return out


def join_step(kind, cond, left, right, cols, rcols, outer):
    out = []
    for l in left:
        hit = False
        for r in right:
            m = {**l, **r}
            if cond is None or truth(ev(cond, {**outer, **finish(m, cols)})) == 1:
                out.append(m)
                hit = True
        if kind == "LEFT" and not hit:
            out.append({**l, **{a + "." + c.lower(): None for a, c in rcols}})
    return out


def build(tables, frm, outer):
    cols, envs = load(tables, frm[0], outer)
    for kind, ref, cond in frm[1]:
        rcols, renvs = load(tables, ref, outer)
        cols = cols + rcols
        envs = join_step(kind, cond, envs, renvs, cols, rcols, outer)
    return cols, [{**outer, **finish(e, cols)} for e in envs]
