def execute(q, outer):
    """Run a parsed query; returns (column names, rows)."""
    tables = outer["__tables__"]
    if q.get("with"):
        tables = dict(tables)
        outer = {**outer, "__tables__": tables}
        for name, colnames, sub in q["with"]:
            names, rows = execute(sub, outer)
            tables[name.lower()] = (colnames or names, rows)
    if q["from"] is None:
        cols, envs = [], [dict(outer)]
    else:
