import re

TOKEN = re.compile(r"\s*(?:(\d+)|'((?:[^']|'')*)'|([A-Za-z_][A-Za-z_0-9]*)|(\|\||<=|>=|<>|!=|[-+*/%()=<>,;.]))")
KEYWORDS_END = {"FROM", "WHERE", "GROUP", "ORDER", "LIMIT", "HAVING", "AS"}


def tokenize(sql):
    toks, pos = [], 0
    sql = sql.rstrip()
    while pos < len(sql):
        m = TOKEN.match(sql, pos)
        if not m:
            raise ValueError("syntax error near %r" % sql[pos:pos + 10])
        pos = m.end()
        if m.group(1) is not None:
            toks.append(("num", int(m.group(1))))
        elif m.group(2) is not None:
            toks.append(("str", m.group(2).replace("''", "'")))
        elif m.group(3) is not None:
            toks.append(("id", m.group(3)))
        else:
            toks.append(("op", m.group(4)))
    toks.append(("eof", None))
    return toks


class Parser:
    def __init__(self, toks):
        self.t = toks
        self.i = 0

    def peek(self):
        return self.t[self.i]

    def kw(self, *words):
        k, v = self.t[self.i]
        return k == "id" and v.upper() in words

    def op(self, *ops):
        k, v = self.t[self.i]
        return k == "op" and v in ops

    def next(self):
        tok = self.t[self.i]
        self.i += 1
        return tok

    def expect_op(self, o):
        if not self.op(o):
            raise ValueError("expected %s" % o)
        self.i += 1

    def expect_kw(self, w):
        if not self.kw(w):
            raise ValueError("expected %s" % w)
        self.i += 1

    def parse_select(self):
        self.expect_kw("SELECT")
        items = []
        while True:
            e = self.expr()
            name = None
            if self.kw("AS"):
                self.i += 1
                name = self.next()[1]
            elif self.peek()[0] == "id" and not self.kw(*KEYWORDS_END):
                name = self.next()[1]
            items.append((e, name))
            if self.op(","):
                self.i += 1
                continue
            break
        while self.op(";"):
            self.i += 1
        if self.peek()[0] != "eof":
            raise ValueError("unexpected trailing input")
        return items

    def expr(self):
        return self.or_()

    def or_(self):
        l = self.and_()
        while self.kw("OR"):
            self.i += 1
            l = ("or", l, self.and_())
        return l

    def and_(self):
        l = self.not_()
        while self.kw("AND"):
            self.i += 1
            l = ("and", l, self.not_())
        return l

    def not_(self):
        if self.kw("NOT"):
            self.i += 1
            return ("not", self.not_())
        return self.cmp()

    def cmp(self):
        l = self.add()
        while True:
            if self.op("=", "!=", "<>", "<", "<=", ">", ">="):
                o = self.next()[1]
                l = ("cmp", o, l, self.add())
            elif self.kw("IS"):
                self.i += 1
                neg = False
                if self.kw("NOT"):
                    self.i += 1
                    neg = True
                self.expect_kw("NULL")
                l = ("isnull", l, neg)
            elif self.kw("NOT", "IN", "LIKE", "BETWEEN"):
                neg = False
                if self.kw("NOT"):
                    self.i += 1
                    neg = True
                if self.kw("IN"):
                    self.i += 1
                    self.expect_op("(")
                    items = [self.expr()]
                    while self.op(","):
                        self.i += 1
                        items.append(self.expr())
                    self.expect_op(")")
                    l = ("in", l, items, neg)
                elif self.kw("LIKE"):
                    self.i += 1
                    l = ("like", l, self.add(), neg)
                elif self.kw("BETWEEN"):
                    self.i += 1
                    a = self.add()
                    self.expect_kw("AND")
                    b = self.add()
                    l = ("between", l, a, b, neg)
                else:
                    raise ValueError("syntax error")
            else:
                return l

    def add(self):
        l = self.mul()
        while self.op("+", "-"):
            o = self.next()[1]
            l = ("bin", o, l, self.mul())
        return l

    def mul(self):
        l = self.concat()
        while self.op("*", "/", "%"):
            o = self.next()[1]
            l = ("bin", o, l, self.concat())
        return l

    def concat(self):
        l = self.unary()
        while self.op("||"):
            self.i += 1
            l = ("bin", "||", l, self.unary())
        return l

    def unary(self):
        if self.op("-"):
            self.i += 1
            return ("neg", self.unary())
        if self.op("+"):
            self.i += 1
            return self.unary()
        return self.primary()

    def primary(self):
        k, v = self.next()
        if k in ("num", "str"):
            return ("lit", v)
        if k == "op" and v == "(":
            e = self.expr()
            self.expect_op(")")
            return e
        if k == "id":
            u = v.upper()
            if u == "NULL":
                return ("lit", None)
            if u == "CASE":
                return self.case()
            if self.op("("):
                self.i += 1
                args = []
                if not self.op(")"):
                    args.append(self.expr())
                    while self.op(","):
                        self.i += 1
                        args.append(self.expr())
                self.expect_op(")")
                return ("func", u, args)
            return ("col", v)
        raise ValueError("syntax error")

    def case(self):
        operand = None
        if not self.kw("WHEN"):
            operand = self.expr()
        whens, els = [], None
        while self.kw("WHEN"):
            self.i += 1
            c = self.expr()
            self.expect_kw("THEN")
            whens.append((c, self.expr()))
        if self.kw("ELSE"):
            self.i += 1
            els = self.expr()
        self.expect_kw("END")
        return ("case", operand, whens, els)


def truth(v):
    if v is None:
        return None
    if isinstance(v, str):
        m = re.match(r"\s*[-+]?\d+", v)
        return 1 if m and int(m.group()) != 0 else 0
    return 1 if v != 0 else 0


def sortkey(v):
    return (1, v) if isinstance(v, str) else (0, v)


def to_num(v):
    if isinstance(v, str):
        m = re.match(r"\s*[-+]?\d+", v)
        return int(m.group()) if m else 0
    return v


def to_text(v):
    return v if isinstance(v, str) else str(v)


def like(s, p):
    rx = "".join(".*" if c == "%" else "." if c == "_" else re.escape(c) for c in p)
    return re.fullmatch(rx, s, re.S | re.I) is not None


def ev(n, row=None):
    t = n[0]
    if t == "lit":
        return n[1]
    if t == "neg":
        v = ev(n[1], row)
        return None if v is None else -to_num(v)
    if t == "bin":
        o = n[1]
        a, b = ev(n[2], row), ev(n[3], row)
        if a is None or b is None:
            return None
        if o == "||":
            return to_text(a) + to_text(b)
        a, b = to_num(a), to_num(b)
        if o == "+":
            return a + b
        if o == "-":
            return a - b
        if o == "*":
            return a * b
        if b == 0:
            return None
        q = abs(a) // abs(b)
        if o == "/":
            return q if (a < 0) == (b < 0) else -q
        return a - b * (q if (a < 0) == (b < 0) else -q)
    if t == "cmp":
        a, b = ev(n[2], row), ev(n[3], row)
        if a is None or b is None:
            return None
        a, b = sortkey(a), sortkey(b)
        return int({"=": a == b, "!=": a != b, "<>": a != b, "<": a < b,
                    "<=": a <= b, ">": a > b, ">=": a >= b}[n[1]])
    if t == "and":
        a = truth(ev(n[1], row))
        if a == 0:
            return 0
        b = truth(ev(n[2], row))
        if b == 0:
            return 0
        return None if a is None or b is None else 1
    if t == "or":
        a = truth(ev(n[1], row))
        if a == 1:
            return 1
        b = truth(ev(n[2], row))
        if b == 1:
            return 1
        return None if a is None or b is None else 0
    if t == "not":
        a = truth(ev(n[1], row))
        return None if a is None else 1 - a
    if t == "isnull":
        r = ev(n[1], row) is None
        return int(r != n[2])
    if t == "in":
        x = ev(n[1], row)
        if x is None:
            return None
        res, saw = 0, False
        for it in n[2]:
            v = ev(it, row)
            if v is None:
                saw = True
            elif sortkey(v) == sortkey(x):
                res = 1
                break
        if res == 0 and saw:
            return None
        return 1 - res if n[3] else res
    if t == "like":
        a, p = ev(n[1], row), ev(n[2], row)
        if a is None or p is None:
            return None
        r = like(to_text(a), to_text(p))
        return int(r != n[3])
    if t == "between":
        x, lo, hi = ev(n[1], row), ev(n[2], row), ev(n[3], row)
        parts = []
        for ok in ((None if x is None or lo is None else sortkey(x) >= sortkey(lo)),
                   (None if x is None or hi is None else sortkey(x) <= sortkey(hi))):
            parts.append(ok)
        if False in parts:
            r = 0
        elif None in parts:
            return None
        else:
            r = 1
        return 1 - r if n[4] else r
    if t == "case":
        if n[1] is None:
            for c, v in n[2]:
                if truth(ev(c, row)) == 1:
                    return ev(v, row)
        else:
            x = ev(n[1], row)
            for c, v in n[2]:
                w = ev(c, row)
                if x is not None and w is not None and sortkey(x) == sortkey(w):
                    return ev(v, row)
        return ev(n[3], row) if n[3] is not None else None
    if t == "func":
        return func(n[1], [lambda a=a: ev(a, row) for a in n[2]])
    raise ValueError("cannot evaluate %r" % (n,))


def func(name, args):
    if name == "COALESCE":
        for a in args:
            v = a()
            if v is not None:
                return v
        return None
    vals = [a() for a in args]
    if name == "NULLIF":
        a, b = vals
        return None if a is not None and b is not None and sortkey(a) == sortkey(b) else a
    if not vals:
        raise ValueError("bad call to " + name)
    v = vals[0]
    if v is None:
        return None
    if name == "UPPER":
        return to_text(v).upper()
    if name == "LOWER":
        return to_text(v).lower()
    if name == "LENGTH":
        return len(to_text(v))
    if name == "ABS":
        return abs(to_num(v))
    if name == "SUBSTR":
        s = to_text(v)
        if len(vals) < 2 or vals[1] is None:
            return None
        start = to_num(vals[1])
        if len(vals) > 2:
            if vals[2] is None:
                return None
            ln = to_num(vals[2])
            if ln < 0:
                end, start = start, start + ln
                end = end
                lo, hi = start, end
            else:
                lo, hi = start, start + ln
        else:
            lo, hi = start, len(s) + 1
        if start == 0 and len(vals) <= 2:
            lo = 1
        lo, hi = max(lo, 1), min(hi, len(s) + 1)
        return s[lo - 1:hi - 1] if hi > lo else ""
    raise ValueError("no such function: " + name)


class Database:
    def __init__(self, tables):
        self.tables = tables

    def query(self, sql):
        items = Parser(tokenize(sql)).parse_select()
        return [tuple(ev(e) for e, _ in items)]
