        raise ValueError("syntax error")

    def ident(self, v):
        u = v.upper()
        if u == "NULL":
            return ("lit", None)
        if u == "CASE":
            return self.case()
        if self.op("("):
            self.i += 1
            args = [] if self.op(")") else self.comma_list(self.expr)
            self.expect_op(")")
            return ("func", u, args)
        return ("col", v)

    def case(self):
        operand = None if self.kw("WHEN") else self.expr()
        whens, els = [], None
        while self.kw("WHEN"):
            self.i += 1
            c = self.expr()
            self.expect_kw("THEN")
            whens.append((c, self.expr()))
        if self.kw("ELSE"):
            self.i += 1
            els = self.expr()
        self.expect_kw("END")
        return ("case", operand, whens, els)
