from .funcs import call
from .values import arith, like, sortkey, to_num, to_text, truth

CMP = {
    "=": lambda a, b: a == b, "!=": lambda a, b: a != b,
    "<>": lambda a, b: a != b, "<": lambda a, b: a < b,
    "<=": lambda a, b: a <= b, ">": lambda a, b: a > b,
    ">=": lambda a, b: a >= b,
}


def tri_and(a, b):
    if a == 0 or b == 0:
        return 0
    return None if a is None or b is None else 1


def tri_or(a, b):
    if a == 1 or b == 1:
        return 1
    return None if a is None or b is None else 0


def compare(o, a, b):
    if a is None or b is None:
        return None
    return int(CMP[o](sortkey(a), sortkey(b)))


def in_list(x, vals):
    if x is None:
        return None
    saw = False
    for v in vals:
        if v is None:
            saw = True
        elif sortkey(v) == sortkey(x):
            return 1
    return None if saw else 0


def between(x, lo, hi):
    return tri_and(truth(compare(">=", x, lo)), truth(compare("<=", x, hi)))


def neg_if(r, neg):
    return 1 - r if neg and r is not None else r


def case(n, row):
    x = None if n[1] is None else ev(n[1], row)
    for c, v in n[2]:
        w = ev(c, row)
        if n[1] is None:
