        if hit:
            return ev(v, row)
    return None if n[3] is None else ev(n[3], row)


def ev(n, row=None):
    t = n[0]
    if t == "lit":
        return n[1]
    if t == "neg":
        v = ev(n[1], row)
        return None if v is None else -to_num(v)
    if t == "bin":
        return arith(n[1], ev(n[2], row), ev(n[3], row))
    if t == "cmp":
        return compare(n[1], ev(n[2], row), ev(n[3], row))
    if t == "and":
        return tri_and(truth(ev(n[1], row)), truth(ev(n[2], row)))
    if t == "or":
        return tri_or(truth(ev(n[1], row)), truth(ev(n[2], row)))
    if t == "not":
        return neg_if(truth(ev(n[1], row)), True)
    if t == "isnull":
        return int((ev(n[1], row) is None) != n[2])
