from .primary import Primary
from .parser import KEYWORDS_END


class Parser(Primary):
    def parse_select(self):
        self.expect_kw("SELECT")
        q = {"distinct": False, "from": None, "where": None,
             "order": [], "limit": None, "offset": None}
        if self.kw("DISTINCT"):
            self.i += 1
            q["distinct"] = True
        q["items"] = self.comma_list(self.item)
        if self.kw("FROM"):
            self.i += 1
            q["from"] = self.table_ref()
        self.clauses(q)
        while self.op(";"):
            self.i += 1
        if self.peek()[0] != "eof":
            raise ValueError("unexpected trailing input")
        return q

    def table_ref(self):
        name = self.next()[1]
        alias = None
        if self.kw("AS"):
            self.i += 1
            alias = self.next()[1]
        elif self.peek()[0] == "id" and not self.kw(*KEYWORDS_END):
            alias = self.next()[1]
        return (name, alias or name)

    def item(self):
        if self.op("*"):
            self.i += 1
            return (("star", None), None)
        e = self.expr()
        name = None
        if self.kw("AS"):
            self.i += 1
            name = self.next()[1]
        elif self.peek()[0] == "id" and not self.kw(*KEYWORDS_END):
            name = self.next()[1]
        return (e, name)
