from .primary import Primary
from .parser import KEYWORDS_END
from .clauses import Clauses


class Parser(Clauses, Primary):
    def parse_select(self):
        self.expect_kw("SELECT")
        q = {"distinct": False, "from": None, "where": None,
             "order": [], "limit": None, "offset": None}
        if self.kw("DISTINCT"):
            self.i += 1
            q["distinct"] = True
        q["items"] = self.comma_list(self.item)
        if self.kw("FROM"):
            self.i += 1
            q["from"] = self.table_ref()
        self.clauses(q)
        while self.op(";"):
            self.i += 1
        if self.peek()[0] != "eof":
            raise ValueError("unexpected trailing input")
        return q

    def alias(self):
        if self.kw("AS"):
            self.i += 1
            return self.next()[1]
        if self.peek()[0] == "id" and not self.kw(*KEYWORDS_END):
            return self.next()[1]
        return None

    def table_ref(self):
        name = self.next()[1]
        return (name, self.alias() or name)

    def item(self):
        if self.op("*"):
            self.i += 1
            return (("star", None), None)
        e = self.expr()
        return (e, self.alias())
