from .evaluator import ev
from .values import sortkey


def okey(v):
    return (0, 0) if v is None else (1,) + sortkey(v)


def expand(q, cols):
    out = []
    for e, name in q["items"]:
        if e[0] == "star":
            for al, c in cols:
                if e[1] is None or e[1].lower() == al:
                    out.append((("col", al, c), c))
        else:
            out.append((e, name))
    return out


def order_value(term, items, vals, env):
    if term[0] == "lit" and isinstance(term[1], int):
        return vals[term[1] - 1]
    if term[0] == "col" and term[1] is None:
        for i, (_, name) in enumerate(items):
            if name is not None and name.lower() == term[2].lower():
                return vals[i]
    return ev(term, env)


def run(q, cols, envs):
    items = expand(q, cols)
    rows = [(tuple(ev(e, env) for e, _ in items), env) for env in envs]
    for term, desc in reversed(q["order"]):
        rows.sort(key=lambda r: okey(order_value(term, items, r[0], r[1])), reverse=desc)
    out = [r[0] for r in rows]
    if q["distinct"]:
        seen, uniq = set(), []
        for r in out:
            if r not in seen:
                seen.add(r)
                uniq.append(r)
        out = uniq
    off = ev(q["offset"]) if q["offset"] is not None else 0
    out = out[off:]
    if q["limit"] is not None:
        lim = ev(q["limit"])
        out = out[:lim] if lim >= 0 else out
    return out
