    envs = row["__group__"]
    if arg is None:
        return len(envs)
    vals = [ev(arg, e) for e in envs]
    vals = [v for v in vals if v is not None]
    if distinct:
        vals = list(dict.fromkeys(vals))
    if name == "COUNT":
