    def from_clause(self):
        base = self.table_ref()
        joins = []
        while True:
            if self.op(","):
                self.i += 1
                joins.append(("CROSS", self.table_ref(), None))
                continue
            kind = None
            if self.kw("INNER"):
                self.i += 1
                kind = "INNER"
            elif self.kw("CROSS"):
                self.i += 1
                kind = "CROSS"
            elif self.kw("LEFT"):
                self.i += 1
                if self.kw("OUTER"):
                    self.i += 1
                kind = "LEFT"
            if not self.kw("JOIN"):
                if kind is not None:
                    raise ValueError("expected JOIN")
                return (base, joins)
            self.i += 1
            ref = self.table_ref()
            cond = None
            if self.kw("ON"):
                self.i += 1
                cond = self.expr()
            joins.append((kind or "INNER", ref, cond))
