"""Tokenizer, parser and evaluator for minisql expressions (checkpoint 1)."""
import re


class SQLError(Exception):
    pass


_TOKEN_RE = re.compile(r"""
    (?P<ws>\s+)
  | (?P<num>\d+)
  | (?P<str>'(?:[^']|'')*')
  | (?P<ident>[A-Za-z_][A-Za-z_0-9]*)
  | (?P<op>\|\||<>|!=|<=|>=|==|[=<>+\-*/%(),;])
""", re.VERBOSE)

_NUM_PREFIX = re.compile(r"\s*[+-]?\d+")


def tokenize(sql):
    tokens = []
    pos = 0
    while pos < len(sql):
        m = _TOKEN_RE.match(sql, pos)
        if not m:
            raise SQLError(f'unrecognized token: "{sql[pos]}"')
        pos = m.end()
        kind = m.lastgroup
        if kind == 'ws':
            continue
        val = m.group()
        if kind == 'str':
            val = val[1:-1].replace("''", "'")
        tokens.append((kind, val))
    return tokens


# ---- value helpers -------------------------------------------------------

def to_num(v):
    """Numeric value of a SQL value, following SQLite's leading-number rule."""
    if v is None or isinstance(v, int):
        return v
    m = _NUM_PREFIX.match(v)
    return int(m.group()) if m else 0


def text(v):
    return str(v) if isinstance(v, int) else v


def tri(v):
    """SQL truth value: True, False or None (NULL)."""
    if v is None:
        return None
    return to_num(v) != 0


def from_tri(t):
    return None if t is None else (1 if t else 0)


def and3(a, b):
    if a is False or b is False:
        return False
    if a is None or b is None:
        return None
    return True


def or3(a, b):
    if a is True or b is True:
        return True
    if a is None or b is None:
        return None
    return False


def not3(a):
    return None if a is None else (not a)


def cmp_values(a, b):
    """-1, 0, 1, or None if either side is NULL. Numbers sort before text."""
    if a is None or b is None:
        return None
    if isinstance(a, str) != isinstance(b, str):
        return -1 if isinstance(a, int) else 1
    return (a > b) - (a < b)
