class Parser:
    """Recursive-descent parser that evaluates expressions as it reads them.

    Expressions have no side effects, so eager evaluation during the parse is
    equivalent to building a tree first.
    """

    def __init__(self, tokens):
        self.toks = tokens
        self.pos = 0

    def peek(self, ahead=0):
        i = self.pos + ahead
        return self.toks[i] if i < len(self.toks) else (None, None)

    def advance(self):
        t = self.peek()
        self.pos += 1
        return t

    def at_end(self):
        return self.pos >= len(self.toks)

    def is_kw(self, word, ahead=0):
        k, v = self.peek(ahead)
        return k == 'ident' and v.upper() == word

    def is_op(self, op):
        return self.peek() == ('op', op)

    def match_kw(self, word):
        if self.is_kw(word):
            self.pos += 1
            return True
        return False

    def match_op(self, op):
        if self.is_op(op):
            self.pos += 1
            return True
        return False

    def expect_kw(self, word):
        if not self.match_kw(word):
            self.syntax_error()

    def expect_op(self, op):
        if not self.match_op(op):
            self.syntax_error()

    def syntax_error(self):
        k, v = self.peek()
        if k is None:
            raise SQLError('incomplete input')
        raise SQLError(f'near "{v}": syntax error')

    def select_statement(self):
        self.expect_kw('SELECT')
        values = []
        while True:
            values.append(self.expr())
            if self.match_kw('AS'):
                self.advance()
            elif self.peek()[0] == 'ident' and not self.is_kw('FROM'):
                self.advance()  # alias without AS
            if not self.match_op(','):
                break
        if self.is_kw('FROM'):
            raise SQLError('FROM is not supported yet')
        self.match_op(';')
        if not self.at_end():
            self.syntax_error()
        return [tuple(values)]
