def _no_env(tbl, name):
    raise SQLError(f'no such column: {name}')


def _const(node):
    return evaluate(node, _no_env)


def _sort_key(v):
    if v is None:
        return (0, 0)
    if isinstance(v, int):
        return (1, v)
    return (2, v)


def _limit_value(node):
    if node is None:
        return None
    v = _const(node)
    return None if v is None else int(to_num(v))


def _output_columns(items, scope):
    """Expand * and alias.* into (expression, alias) pairs."""
    outs = []
    for item in items:
        if item[0] in ('star', 'tstar'):
            if not scope.sources:
                raise SQLError('no tables specified')
            for i, (alias, cols) in enumerate(scope.sources):
                if item[0] == 'tstar' and alias != item[1].lower():
