"""Tokenizer, parser and evaluator for minisql expressions (checkpoint 1)."""
import re


class SQLError(Exception):
    pass


_TOKEN_RE = re.compile(r"""
    (?P<ws>\s+)
  | (?P<num>\d+)
  | (?P<str>'(?:[^']|'')*')
  | (?P<ident>[A-Za-z_][A-Za-z_0-9]*)
  | (?P<op>\|\||<>|!=|<=|>=|==|[=<>+\-*/%(),;])
""", re.VERBOSE)

_NUM_PREFIX = re.compile(r"\s*[+-]?\d+")


def tokenize(sql):
    tokens = []
    pos = 0
    while pos < len(sql):
        m = _TOKEN_RE.match(sql, pos)
        if not m:
            raise SQLError(f'unrecognized token: "{sql[pos]}"')
        pos = m.end()
        kind = m.lastgroup
        if kind == 'ws':
            continue
        val = m.group()
        if kind == 'str':
            val = val[1:-1].replace("''", "'")
        tokens.append((kind, val))
    return tokens


# ---- value helpers -------------------------------------------------------

def to_num(v):
    """Numeric value of a SQL value, following SQLite's leading-number rule."""
    if v is None or isinstance(v, int):
        return v
    m = _NUM_PREFIX.match(v)
    return int(m.group()) if m else 0


def text(v):
    return str(v) if isinstance(v, int) else v


def tri(v):
    """SQL truth value: True, False or None (NULL)."""
    if v is None:
        return None
    return to_num(v) != 0


def from_tri(t):
    return None if t is None else (1 if t else 0)


def and3(a, b):
    if a is False or b is False:
        return False
    if a is None or b is None:
        return None
    return True


def or3(a, b):
    if a is True or b is True:
        return True
    if a is None or b is None:
        return None
    return False


def not3(a):
    return None if a is None else (not a)


def cmp_values(a, b):
    """-1, 0, 1, or None if either side is NULL. Numbers sort before text."""
    if a is None or b is None:
        return None
    if isinstance(a, str) != isinstance(b, str):
        return -1 if isinstance(a, int) else 1
    return (a > b) - (a < b)


def arith(op, a, b):
    if a is None or b is None:
        return None
    a, b = to_num(a), to_num(b)
    if op == '+':
        return a + b
    if op == '-':
        return a - b
    if op == '*':
        return a * b
    if b == 0:
        return None
    if op == '/':
        q = abs(a) // abs(b)
        return -q if (a < 0) != (b < 0) else q
    if op == '%':
        r = abs(a) % abs(b)
        return -r if a < 0 else r
    raise SQLError(f'unknown operator {op}')


def like(s, pat):
    if s is None or pat is None:
        return None
    regex = []
    for ch in text(pat):
        if ch == '%':
            regex.append('.*')
        elif ch == '_':
            regex.append('.')
        else:
            regex.append(re.escape(ch))
    return re.fullmatch(''.join(regex), text(s), re.DOTALL | re.IGNORECASE) is not None


_MISSING = object()


def _substr(s, start, length=_MISSING):
    if s is None or start is None or length is None:
        return None
    s = text(s)
    n = len(s)
    start = to_num(start)
    raw_first = n + start + 1 if start < 0 else start
    if length is _MISSING:
        lo, hi = raw_first, n
    else:
        L = to_num(length)
        if L >= 0:
            lo, hi = raw_first, raw_first + L - 1
        else:
            lo, hi = raw_first + L, raw_first - 1
    lo, hi = max(lo, 1), min(hi, n)
    return s[lo - 1:hi] if lo <= hi else ''


def _null_strict(fn):
    def wrapper(*args):
        if args[0] is None:
            return None
        return fn(*args)
    return wrapper


def _coalesce(*args):
    for a in args:
        if a is not None:
            return a
    return None


def _nullif(a, b):
    return None if cmp_values(a, b) == 0 else a


FUNCTIONS = {
    'UPPER': (1, 1, _null_strict(lambda s: text(s).upper())),
    'LOWER': (1, 1, _null_strict(lambda s: text(s).lower())),
    'LENGTH': (1, 1, _null_strict(lambda s: len(text(s)))),
    'ABS': (1, 1, _null_strict(lambda n: abs(to_num(n)))),
    'SUBSTR': (2, 3, _null_strict(_substr)),
    'COALESCE': (1, None, _coalesce),
    'NULLIF': (2, 2, _nullif),
}

CMP_OPS = {'=', '==', '!=', '<>', '<', '<=', '>', '>='}


def _compare(op, a, b):
    c = cmp_values(a, b)
    if c is None:
        return None
    return int({
        '=': c == 0, '==': c == 0, '!=': c != 0, '<>': c != 0,
        '<': c < 0, '<=': c <= 0, '>': c > 0, '>=': c >= 0,
    }[op])


# ---- parser / evaluator ----------------------------------------------------

class Parser:
    """Recursive-descent parser that evaluates expressions as it reads them.

    Expressions have no side effects and no column references yet, so evaluating
    eagerly during the parse is equivalent to building a tree first.
    """

    def __init__(self, tokens):
        self.toks = tokens
        self.pos = 0

