    def peek(self, ahead=0):
        i = self.pos + ahead
        return self.toks[i] if i < len(self.toks) else (None, None)

    def advance(self):
        t = self.peek()
        self.pos += 1
        return t

    def at_end(self):
        return self.pos >= len(self.toks)

    def is_kw(self, word, ahead=0):
        k, v = self.peek(ahead)
        return k == 'ident' and v.upper() == word

    def is_op(self, op, ahead=0):
        k, v = self.peek(ahead)
        return k == 'op' and v == op

    def match_kw(self, word):
        if self.is_kw(word):
            self.pos += 1
            return True
        return False

    def match_op(self, op):
        if self.is_op(op):
            self.pos += 1
            return True
        return False

    def expect_kw(self, word):
        if not self.match_kw(word):
            self.syntax_error()

    def expect_op(self, op):
        if not self.match_op(op):
            self.syntax_error()

    def syntax_error(self):
        k, v = self.peek()
        if k is None:
            raise SQLError('incomplete input')
        raise SQLError(f'near "{v}": syntax error')

    # statements
    def select_statement(self):
        self.expect_kw('SELECT')
        values = []
        while True:
            value = self.expr()
            if self.match_kw('AS'):
                self.advance()
            elif self.peek()[0] == 'ident' and not self.is_kw('FROM'):
                self.advance()  # alias without AS
            values.append(value)
            if not self.match_op(','):
                break
        if self.is_kw('FROM'):
            raise SQLError('FROM is not supported yet')
        self.match_op(';')
        if not self.at_end():
            self.syntax_error()
        return [tuple(values)]

    # expressions, lowest precedence first
    def expr(self):
        return self.or_expr()

    def or_expr(self):
        v = self.and_expr()
        while self.match_kw('OR'):
            v = from_tri(or3(tri(v), tri(self.and_expr())))
        return v

    def and_expr(self):
        v = self.not_expr()
        while self.match_kw('AND'):
            v = from_tri(and3(tri(v), tri(self.not_expr())))
        return v

    def not_expr(self):
        if self.match_kw('NOT'):
            return from_tri(not3(tri(self.not_expr())))
        return self.predicate()

    def predicate(self):
        left = self.additive()
        while True:
            k, v = self.peek()
            if k == 'op' and v in CMP_OPS:
                self.advance()
                left = _compare(v, left, self.additive())
                continue
            if self.match_kw('IS'):
                negate = self.match_kw('NOT')
                right = self.additive()
                if left is None or right is None:
                    same = left is None and right is None
                else:
                    same = cmp_values(left, right) == 0
                left = int(same != negate)
                continue
            negate = False
            if self.is_kw('NOT') and any(self.is_kw(w, 1) for w in ('BETWEEN', 'IN', 'LIKE')):
                self.advance()
                negate = True
            if self.match_kw('BETWEEN'):
                lo = self.additive()
                self.expect_kw('AND')
                hi = self.additive()
                r = and3(
                    tri(_compare('>=', left, lo)),
                    tri(_compare('<=', left, hi)),
                )
            elif self.match_kw('IN'):
                self.expect_op('(')
                items = [self.expr()]
                while self.match_op(','):
                    items.append(self.expr())
                self.expect_op(')')
                r = self._in(left, items)
            elif self.match_kw('LIKE'):
                r = like(left, self.additive())
            else:
                if negate:
                    self.syntax_error()
                return left
            left = from_tri(not3(tri(r))) if negate else from_tri(tri(r))

    @staticmethod
    def _in(x, items):
        if x is None:
            return None
        saw_null = False
        for item in items:
            c = cmp_values(x, item)
            if c == 0:
                return True
            if c is None:
                saw_null = True
        return None if saw_null else False

    def additive(self):
        v = self.multiplicative()
        while True:
            if self.is_op('+') or self.is_op('-'):
                op = self.advance()[1]
                v = arith(op, v, self.multiplicative())
            else:
                return v

    def multiplicative(self):
        v = self.concat()
        while self.is_op('*') or self.is_op('/') or self.is_op('%'):
            op = self.advance()[1]
            v = arith(op, v, self.concat())
        return v

    def concat(self):
        v = self.unary()
        while self.match_op('||'):
            w = self.unary()
            v = None if v is None or w is None else text(v) + text(w)
        return v

    def unary(self):
        if self.match_op('-'):
            v = self.unary()
            return None if v is None else -to_num(v)
        if self.match_op('+'):
            return self.unary()
        return self.primary()

    def primary(self):
        k, v = self.peek()
        if k is None:
            self.syntax_error()
        self.advance()
        if k == 'num':
            return int(v)
        if k == 'str':
            return v
        if k == 'op' and v == '(':
            inner = self.expr()
            self.expect_op(')')
            return inner
        if k == 'ident':
            up = v.upper()
            if up == 'NULL':
                return None
            if up == 'CASE':
                return self.case()
            if self.is_op('('):
                return self.call(up)
            raise SQLError(f'no such column: {v}')
        self.pos -= 1
        self.syntax_error()

    def case(self):
        base = _MISSING
        if not self.is_kw('WHEN'):
            base = self.expr()
        branches = []
        while self.match_kw('WHEN'):
            cond = self.expr()
            self.expect_kw('THEN')
            branches.append((cond, self.expr()))
        if not branches:
            self.syntax_error()
        else_v = None
        if self.match_kw('ELSE'):
            else_v = self.expr()
        self.expect_kw('END')
        for cond, val in branches:
            if base is _MISSING:
                hit = tri(cond) is True
            else:
                hit = cmp_values(base, cond) == 0
            if hit:
                return val
        return else_v

    def call(self, name):
        self.expect_op('(')
        args = []
        if not self.is_op(')'):
            args.append(self.expr())
            while self.match_op(','):
                args.append(self.expr())
        self.expect_op(')')
        if name not in FUNCTIONS:
            raise SQLError(f'no such function: {name}')
        lo, hi, fn = FUNCTIONS[name]
        if len(args) < lo or (hi is not None and len(args) > hi):
            raise SQLError(f'wrong number of arguments to function {name}()')
        return fn(*args)


def run_select(sql):
    tokens = tokenize(sql)
    if not tokens:
        raise SQLError('empty query')
    if tokens[0] != ('ident', 'SELECT') and not (tokens[0][0] == 'ident' and tokens[0][1].upper() == 'SELECT'):
        raise SQLError('only SELECT is supported')
    return Parser(tokens).select_statement()
