"""Parser: turns SQL text into an AST (tuples), evaluated later per row."""
from minisql.sql import SQLError, tokenize

RESERVED = {
    'FROM', 'WHERE', 'ORDER', 'LIMIT', 'OFFSET', 'GROUP', 'HAVING', 'JOIN', 'ON',
    'INNER', 'LEFT', 'UNION', 'AND', 'OR', 'NOT', 'IS', 'IN', 'LIKE', 'BETWEEN',
    'ASC', 'DESC', 'THEN', 'ELSE', 'WHEN', 'END', 'AS', 'CASE', 'NULL', 'SELECT', 'DISTINCT',
}


class Parser:
    def __init__(self, tokens):
        self.toks = tokens
        self.pos = 0

    def peek(self, ahead=0):
        i = self.pos + ahead
        return self.toks[i] if i < len(self.toks) else (None, None)

    def advance(self):
        t = self.peek()
        self.pos += 1
        return t

    def at_end(self):
        return self.pos >= len(self.toks)

    def is_kw(self, word, ahead=0):
        k, v = self.peek(ahead)
        return k == 'ident' and v.upper() == word

    def is_op(self, op, ahead=0):
        return self.peek(ahead) == ('op', op)

    def match_kw(self, word):
        if self.is_kw(word):
            self.pos += 1
            return True
        return False

    def match_op(self, op):
        if self.is_op(op):
            self.pos += 1
            return True
        return False

    def expect_kw(self, word):
        if not self.match_kw(word):
            self.syntax_error()

    def expect_op(self, op):
        if not self.match_op(op):
            self.syntax_error()

    def syntax_error(self):
        k, v = self.peek()
        if k is None:
            raise SQLError('incomplete input')
        raise SQLError(f'near "{v}": syntax error')

    def ident(self):
