"""Parser: turns SQL text into an AST (tuples), evaluated later per row."""
from minisql.sql import SQLError, tokenize

RESERVED = {
    'FROM', 'WHERE', 'ORDER', 'LIMIT', 'OFFSET', 'GROUP', 'HAVING', 'JOIN', 'ON',
    'INNER', 'LEFT', 'UNION', 'AND', 'OR', 'NOT', 'IS', 'IN', 'LIKE', 'BETWEEN',
    'ASC', 'DESC', 'THEN', 'ELSE', 'WHEN', 'END', 'AS', 'CASE', 'NULL', 'SELECT', 'DISTINCT',
}


class Parser:
    def __init__(self, tokens):
        self.toks = tokens
        self.pos = 0

    def peek(self, ahead=0):
        i = self.pos + ahead
        return self.toks[i] if i < len(self.toks) else (None, None)

    def advance(self):
        t = self.peek()
        self.pos += 1
        return t

    def at_end(self):
        return self.pos >= len(self.toks)

    def is_kw(self, word, ahead=0):
        k, v = self.peek(ahead)
        return k == 'ident' and v.upper() == word

    def is_op(self, op, ahead=0):
        return self.peek(ahead) == ('op', op)
