    def match_kw(self, word):
        if self.is_kw(word):
            self.pos += 1
            return True
        return False

    def match_op(self, op):
        if self.is_op(op):
            self.pos += 1
            return True
        return False

    def expect_kw(self, word):
        if not self.match_kw(word):
