    def multiplicative(self):
        v = self.concat()
        while self.is_op('*') or self.is_op('/') or self.is_op('%'):
            op = self.advance()[1]
            v = ('bin', op, v, self.concat())
        return v

    def concat(self):
        v = self.unary()
        while self.match_op('||'):
            v = ('bin', '||', v, self.unary())
        return v

    def unary(self):
        if self.match_op('-'):
            return ('neg', self.unary())
        if self.match_op('+'):
            return self.unary()
        return self.primary()
