    def primary(self):
        k, v = self.peek()
        if k is None:
            self.syntax_error()
        if k == 'num':
            self.advance()
            return ('lit', int(v))
        if k == 'str':
            self.advance()
            return ('lit', v)
        if self.match_op('('):
            inner = self.expr()
            self.expect_op(')')
            return inner
        if k != 'ident':
            self.syntax_error()
        up = v.upper()
        if up == 'NULL':
            self.advance()
            return ('lit', None)
        if up == 'CASE' and not self.is_op('(', 1):
            self.advance()
            return self.case()
        if self.is_op('(', 1):
            self.advance()
            return self.call(up)
        if up in RESERVED:
            self.syntax_error()
        self.advance()
        if self.match_op('.'):
            return ('col', v, self.ident())
        return ('col', None, v)
