    def case(self):
        base = None
        if not self.is_kw('WHEN'):
            base = self.expr()
        branches = []
        while self.match_kw('WHEN'):
            cond = self.expr()
            self.expect_kw('THEN')
            branches.append((cond, self.expr()))
        if not branches:
            self.syntax_error()
        else_v = self.expr() if self.match_kw('ELSE') else ('lit', None)
        self.expect_kw('END')
        return ('case', base, branches, else_v)

    def call(self, name):
        self.expect_op('(')
        args = []
        if not self.is_op(')'):
            args.append(self.expr())
            while self.match_op(','):
                args.append(self.expr())
        self.expect_op(')')
        return ('func', name, args)
