"""Evaluator and SELECT execution."""
from minisql.sql import (SQLError, tri, from_tri, and3, or3, not3, to_num, text, arith,
                         cmp_values, like, FUNCTIONS, _compare)


def _in(x, items):
    if x is None:
        return None
    saw_null = False
    for item in items:
        c = cmp_values(x, item)
        if c == 0:
            return True
        if c is None:
            saw_null = True
    return None if saw_null else False


def evaluate(node, env):
    """Evaluate an expression node. env(table, name) returns a column value."""
    ev = lambda n: evaluate(n, env)  # noqa: E731
    k = node[0]
    if k == 'lit':
        return node[1]
    if k == 'col':
        return env(node[1], node[2])
    if k == 'neg':
        v = ev(node[1])
        return None if v is None else -to_num(v)
    if k == 'bin':
        a, b = ev(node[2]), ev(node[3])
        if node[1] == '||':
            return None if a is None or b is None else text(a) + text(b)
        return arith(node[1], a, b)
    if k == 'cmp':
        return _compare(node[1], ev(node[2]), ev(node[3]))
    if k == 'is':
        a, b = ev(node[2]), ev(node[3])
        same = (a is None and b is None) if (a is None or b is None) else cmp_values(a, b) == 0
        return int(same != node[1])
    if k == 'and':
        return from_tri(and3(tri(ev(node[1])), tri(ev(node[2]))))
    if k == 'or':
        return from_tri(or3(tri(ev(node[1])), tri(ev(node[2]))))
    if k == 'not':
        return from_tri(not3(tri(ev(node[1]))))
    if k == 'between':
        neg, x, lo, hi = node[1], ev(node[2]), ev(node[3]), ev(node[4])
        r = and3(tri(_compare('>=', x, lo)), tri(_compare('<=', x, hi)))
        return from_tri(not3(r) if neg else r)
    if k == 'in':
        neg, r = node[1], _in(ev(node[2]), [ev(i) for i in node[3]])
        return from_tri(not3(r) if neg else r)
    if k == 'like':
        neg, r = node[1], tri(like(ev(node[2]), ev(node[3])))
        return from_tri(not3(r) if neg else r)
    if k == 'case':
        base, branches, else_node = node[1], node[2], node[3]
        base_val = None if base is None else ev(base)
        for cond, val in branches:
            if base is None:
                hit = tri(ev(cond)) is True
            else:
                hit = cmp_values(base_val, ev(cond)) == 0
            if hit:
                return ev(val)
        return ev(else_node)
    if k == 'func':
        name, args = node[1], node[2]
        if name not in FUNCTIONS:
            raise SQLError(f'no such function: {name}')
        lo, hi, fn = FUNCTIONS[name]
        if len(args) < lo or (hi is not None and len(args) > hi):
            raise SQLError(f'wrong number of arguments to function {name}()')
        return fn(*[ev(a) for a in args])
    raise SQLError(f'unknown expression node {k}')
