import re

TOKEN = re.compile(r"""\s*(?:(?P<num>\d+)|(?P<str>'(?:[^']|'')*')|(?P<id>[A-Za-z_][A-Za-z_0-9]*)
  |(?P<op>\|\||<=|>=|<>|!=|==|[-+*/%(),=<>;.]))""", re.X)


def tokenize(sql):
    out, pos = [], 0
    sql = sql.rstrip()
    while pos < len(sql):
        m = TOKEN.match(sql, pos)
        if not m:
            raise ValueError("syntax error near %r" % sql[pos:pos + 10])
        pos = m.end()
        if m.group("num") is not None:
            out.append(("num", int(m.group("num"))))
        elif m.group("str") is not None:
            out.append(("str", m.group("str")[1:-1].replace("''", "'")))
        elif m.group("id") is not None:
            out.append(("id", m.group("id")))
        else:
            out.append(("op", m.group("op")))
    out.append(("eof", None))
    return out


def num(v):
    if isinstance(v, int):
        return v
    m = re.match(r"\s*[-+]?\d+", v)
    return int(m.group()) if m else 0


def text(v):
    return v if isinstance(v, str) else str(v)


def sortkey(v):
    return (1, v) if isinstance(v, str) else (0, v)


def truth(v):
    if v is None:
        return None
    return 1 if num(v) != 0 else 0


def like(s, p):
    rx = "".join(".*" if c == "%" else "." if c == "_" else re.escape(c) for c in p)
    return re.fullmatch(rx, s, re.S | re.I) is not None


