    def __init__(self, sql):
        self.t = tokenize(sql)
        self.i = 0

    def peek(self):
        return self.t[self.i]

    def next(self):
        tok = self.t[self.i]
        self.i += 1
        return tok

    def kw(self, *words):
        k, v = self.peek()
        if k == "id" and v.upper() in words:
            return v.upper()
        return None

    def accept_kw(self, w):
        if self.kw(w):
            self.i += 1
            return True
        return False

    def expect_kw(self, w):
        if not self.accept_kw(w):
            raise ValueError("expected " + w)

    def op(self, *ops):
        k, v = self.peek()
        return v if k == "op" and v in ops else None

    def expect_op(self, o):
        if not self.op(o):
            raise ValueError("expected " + o)
        self.i += 1

    def parse_select(self):
        self.expect_kw("SELECT")
        items = []
        while True:
            e = self.expr()
            if self.accept_kw("AS"):
                self.next()
            elif self.peek()[0] == "id" and not self.kw("FROM"):
                self.next()
            items.append(e)
            if self.op(","):
                self.i += 1
            else:
                break
        if self.op(";"):
            self.i += 1
        if self.peek()[0] != "eof":
            raise ValueError("unexpected trailing input")
        return items

    def expr(self):
        return self.or_()

    def or_(self):
        l = self.and_()
        while self.accept_kw("OR"):
            l = ("or", l, self.and_())
        return l

    def and_(self):
        l = self.not_()
        while self.accept_kw("AND"):
            l = ("and", l, self.not_())
        return l

    def not_(self):
        if self.accept_kw("NOT"):
            return ("not", self.not_())
        return self.cmp()

    def cmp(self):
