    n = len(s)
    if length is None:
        lo, hi = start, n + 1
        if start < 0:
            lo = max(n + start + 1, 1)
        lo = max(lo, 1)
        return s[lo - 1:hi - 1]
    if start < 0:
        start = n + start + 1
    if length < 0:
        hi = start
        lo = start + length
    else:
        lo, hi = start, start + length
    lo = max(lo, 1)
    hi = min(hi, n + 1)
    return s[lo - 1:hi - 1] if hi > lo else ""


