    t = e[0]
    if t == "lit":
        return e[1]
    if t == "neg":
        v = ev(e[1])
        return None if v is None else -num(v)
    if t == "arith":
        a, b = ev(e[2]), ev(e[3])
        if a is None or b is None:
            return None
        a, b, o = num(a), num(b), e[1]
        if o == "+":
            return a + b
        if o == "-":
            return a - b
        if o == "*":
            return a * b
        if b == 0:
            return None
        q = abs(a) // abs(b)
        if o == "/":
            return q if (a < 0) == (b < 0) else -q
        r = abs(a) % abs(b)
        return -r if a < 0 else r
    if t == "concat":
        a, b = ev(e[1]), ev(e[2])
        return None if a is None or b is None else text(a) + text(b)
    if t == "cmp":
        return compare(e[1], ev(e[2]), ev(e[3]))
    if t == "and":
        a = truth(ev(e[1]))
        if a == 0:
            return 0
        b = truth(ev(e[2]))
        if b == 0:
            return 0
        return None if a is None or b is None else 1
    if t == "or":
        a = truth(ev(e[1]))
        if a == 1:
            return 1
        b = truth(ev(e[2]))
        if b == 1:
