class ExprMixin:
    def expr(self):
        l = self.and_()
        while self.accept_kw("OR"):
            l = ("or", l, self.and_())
        return l

    def and_(self):
        l = self.not_()
        while self.accept_kw("AND"):
            l = ("and", l, self.not_())
        return l

    def not_(self):
        if self.accept_kw("NOT"):
            return ("not", self.not_())
        return self.cmp()

    def cmp(self):
        l = self.add()
        while True:
            o = self.op("=", "==", "!=", "<>", "<", "<=", ">", ">=")
            if o:
                self.i += 1
                l = ("cmp", {"==": "=", "<>": "!="}.get(o, o), l, self.add())
                continue
            if self.accept_kw("IS"):
                neg = self.accept_kw("NOT")
                self.expect_kw("NULL")
                l = ("isnull", l, neg)
                continue
            save = self.i
            neg = self.accept_kw("NOT")
            if self.accept_kw("BETWEEN"):
                a = self.add()
                self.expect_kw("AND")
                r = ("and", ("cmp", ">=", l, a), ("cmp", "<=", l, self.add()))
            elif self.accept_kw("IN"):
                self.expect_op("(")
                r = ("in", l, self.exprlist(")"))
                self.expect_op(")")
            elif self.accept_kw("LIKE"):
                r = ("like", l, self.add())
            else:
                self.i = save
                return l
            l = ("not", r) if neg else r

    def add(self):
        l = self.mul()
        while self.op("+", "-"):
            o = self.next()[1]
            l = ("arith", o, l, self.mul())
        return l

    def mul(self):
        l = self.concat()
        while self.op("*", "/", "%"):
            o = self.next()[1]
            l = ("arith", o, l, self.concat())
        return l

    def concat(self):
        l = self.unary()
        while self.op("||"):
            self.i += 1
            l = ("concat", l, self.unary())
        return l

    def unary(self):
        if self.op("-"):
            self.i += 1
            return ("neg", self.unary())
        if self.op("+"):
            self.i += 1
            return self.unary()
        return self.primary()

    def primary(self):
        k, v = self.next()
        if k in ("num", "str"):
            return ("lit", v)
        if k == "op" and v == "(":
            e = self.expr()
            self.expect_op(")")
            return e
        if k == "id":
            u = v.upper()
            if u == "NULL":
                return ("lit", None)
            if u == "CASE":
