import re


def num(v):
    if isinstance(v, int):
        return v
    m = re.match(r"\s*[-+]?\d+", v)
    return int(m.group()) if m else 0


def text(v):
    return v if isinstance(v, str) else str(v)


def sortkey(v):
    return (1, v) if isinstance(v, str) else (0, v)


def truth(v):
    return None if v is None else int(num(v) != 0)


def like(s, p):
    rx = "".join(".*" if c == "%" else "." if c == "_" else re.escape(c) for c in p)
    return re.fullmatch(rx, s, re.S | re.I) is not None


def compare(op, a, b):
    if a is None or b is None:
        return None
    a, b = sortkey(a), sortkey(b)
    return int({"=": a == b, "!=": a != b, "<": a < b, "<=": a <= b,
                ">": a > b, ">=": a >= b}[op])


def arith(o, a, b):
    if a is None or b is None:
        return None
    a, b = num(a), num(b)
    if o == "+":
        return a + b
    if o == "-":
        return a - b
    if o == "*":
        return a * b
    if b == 0:
        return None
    if o == "/":
        q = abs(a) // abs(b)
        return q if (a < 0) == (b < 0) else -q
    r = abs(a) % abs(b)
    return -r if a < 0 else r
EOF

