from .values import num, text, compare


def substr(s, start, length=None):
    s = text(s)
    n = len(s)
    if start < 0:
        start = n + start + 1
    if length is None:
        lo, hi = start, n + 1
    elif length < 0:
        lo, hi = start + length, start
    else:
        lo, hi = start, start + length
    lo, hi = max(lo, 1), min(hi, n + 1)
    return s[lo - 1:hi - 1] if hi > lo else ""


def call(name, args, ev):
    if name == "COALESCE":
        for a in args:
            v = ev(a)
            if v is not None:
                return v
        return None
    a = [ev(x) for x in args]
    if name == "NULLIF":
        return None if compare("=", a[0], a[1]) else a[0]
    if name not in ("UPPER", "LOWER", "LENGTH", "ABS", "SUBSTR"):
        raise ValueError("no such function: " + name)
    if not a or a[0] is None:
        return None
    if name == "UPPER":
        return text(a[0]).upper()
    if name == "LOWER":
        return text(a[0]).lower()
    if name == "LENGTH":
        return len(text(a[0]))
    if name == "ABS":
        return abs(num(a[0]))
    if any(x is None for x in a[1:]):
        return None
    return substr(a[0], num(a[1]), num(a[2]) if len(a) > 2 else None)
