def okey(v):
    return (0, 0) if v is None else (1,) + sortkey(v)


class Database:
    def __init__(self, tables):
        self.tables = tables

    def find(self, name):
        for k, v in self.tables.items():
            if k.lower() == name.lower():
                return v
        raise ValueError("no such table: " + name)

    def query(self, sql):
        q = SelectParser(sql).parse_select()
        cols, rows = [], [()]
        if q["table"]:
            tcols, trows = self.find(q["table"][0])
            cols = [(q["table"][1], c) for c in tcols]
            rows = [tuple(r) for r in trows]
        envs = [Env(cols, r) for r in rows]
        if q["where"] is not None:
            envs = [e for e in envs if ev(q["where"], e) not in (None, 0)]
        return self.project(q, cols, envs)

    def project(self, q, cols, envs):
        exprs, names = [], []
        for e, alias in q["items"]:
            if e[0] == "star":
                for qq, c in cols:
                    if e[1] is None or qq.lower() == e[1].lower():
                        exprs.append(("col", qq, c))
                        names.append(c)
            else:
                exprs.append(e)
                names.append(alias or (e[2] if e[0] == "col" else None))
        out = [(tuple(ev(x, env) for x in exprs), env) for env in envs]
        out = self.order(q, exprs, names, out)
        res = [r for r, _ in out]
        if q["distinct"]:
            seen, uniq = set(), []
            for r in res:
                if r not in seen:
                    seen.add(r)
                    uniq.append(r)
            res = uniq
        off = ev(q["offset"]) if q["offset"] is not None else 0
        if q["limit"] is not None:
            lim = ev(q["limit"])
            res = res[off:] if lim < 0 else res[off:off + lim]
        else:
            res = res[off:]
        return res

    def order(self, q, exprs, names, out):
        for term, desc in reversed(q["order"]):
            if term[0] == "lit" and isinstance(term[1], int):
                idx = term[1] - 1
                f = lambda p, idx=idx: p[0][idx]
            elif term[0] == "col" and term[1] is None and any(
                    n and n.lower() == term[2].lower() for n in names):
                idx = [n and n.lower() for n in names].index(term[2].lower())
                f = lambda p, idx=idx: p[0][idx]
            else:
                f = lambda p, t=term: ev(t, p[1])
            out = sorted(out, key=lambda p: okey(f(p)), reverse=desc)
        return out
