        self.cols, self.row = cols, row

    def lookup(self, qual, name):
        n = name.lower()
        for i, (q, c) in enumerate(self.cols):
            if c.lower() == n and (qual is None or q.lower() == qual.lower()):
                return self.row[i]
        raise ValueError("no such column: %s" % name)


def okey(v):
    return (0, 0) if v is None else (1,) + sortkey(v)


def order_rows(q, names, out, ev):
    """out: list of (result tuple, env)."""
    lowered = [n and n.lower() for n in names]
    for term, desc in reversed(q["order"]):
        if term[0] == "lit" and isinstance(term[1], int):
            idx = term[1] - 1
        elif term[0] == "col" and term[1] is None and term[2].lower() in lowered:
            idx = lowered.index(term[2].lower())
        else:
            idx = None
        if idx is not None:
            f = lambda p, i=idx: p[0][i]
        else:
            f = lambda p, t=term: ev(t, p[1])
        out = sorted(out, key=lambda p: okey(f(p)), reverse=desc)
    return out
