from .env import Scope
from .setops import combine, finish


class RunnerMixin:
    def run(self, q, outer=None, ctes=None):
        scope = Scope(self, dict(ctes or {}))
        for name, cols, sub in q["ctes"]:
            if q["recursive"] and sub["sets"]:
                names, rows = self.recurse(name, cols, sub, outer, scope)
            else:
                names, rows = self.run(sub, outer, scope.ctes)
            scope.ctes[name.lower()] = (cols or names, rows)
        names, rows = self.run_one(q, outer, scope)
        for op, allf, body in q["sets"]:
            rows = combine(op, allf, rows, self.run_one(body, outer, scope)[1])
        if q["sets"]:
            rows = finish(q, names, rows)
        return names, rows

    def recurse(self, name, cols, sub, outer, scope):
        names, rows = self.run_one(sub, outer, scope)
        allf, step = sub["sets"][0][1:]
        res = rows if allf else list(dict.fromkeys(rows))
        work, seen = list(res), set(res)
        while work:
            scope.ctes[name.lower()] = (cols or names, work)
            new = self.run_one(step, outer, scope)[1]
            if not allf:
                new = [r for r in dict.fromkeys(new) if r not in seen]
                seen.update(new)
            res, work = res + new, new
        return names, res
