                rows = sorted(rows, key=lambda r: okey(ev(t, r)), reverse=d)
            keys = [tuple(okey(ev(t, r)) for t, _ in w[3]) for r in rows]
            for i, r in enumerate(rows):
                r.wv[id(w)] = one(w, rows, keys, i)


def one(w, rows, keys, i):
    _, call, _, order, fr = w
    name, n, r = call[1], len(rows), rows[i]
    args = call[2] if call[0] == "func" else None
    if name == "ROW_NUMBER":
        return i + 1
    if name == "RANK":
        return keys.index(keys[i]) + 1
    if name == "DENSE_RANK":
        return len(set(keys[:i + 1]))
    if name == "NTILE":
        q, rem = divmod(n, ev(args[0], r))
        big = rem * (q + 1)
        return i // (q + 1) + 1 if i < big else rem + (i - big) // q + 1
    if name in ("LAG", "LEAD"):
        off = ev(args[1], r) if len(args) > 1 else 1
        j = i - off if name == "LAG" else i + off
        if 0 <= j < n:
            return ev(args[0], rows[j])
        return ev(args[2], r) if len(args) > 2 else None
    if fr is None:
        lo, hi = 0, n - 1 - keys[::-1].index(keys[i]) if order else n - 1
    else:
        pos = {"unb_p": 0, "p": -1, "cur": 0, "f": 1, "unb_f": 0}
        (a, am), (b, bm) = fr
        lo = 0 if a == "unb_p" else n - 1 if a == "unb_f" else i + pos[a] * am
        hi = 0 if b == "unb_p" else n - 1 if b == "unb_f" else i + pos[b] * bm
    frame = rows[max(lo, 0):min(hi, n - 1) + 1]
    if name == "FIRST_VALUE":
        return ev(args[0], frame[0]) if frame else None
    if name == "LAST_VALUE":
        return ev(args[0], frame[-1]) if frame else None
    return aggregate(call, type("F", (), {"envs": frame}), ev)
