import re

TOKEN = re.compile(r"""\s*(?:(?P<num>\d+)|(?P<str>'(?:[^']|'')*')|(?P<id>[A-Za-z_][A-Za-z_0-9]*)
  |(?P<op>\|\||<=|>=|<>|!=|==|[-+*/%(),=<>;.]))""", re.X)


def tokenize(sql):
    out, pos = [], 0
    sql = sql.rstrip()
    while pos < len(sql):
        m = TOKEN.match(sql, pos)
        if not m:
            raise ValueError("syntax error near %r" % sql[pos:pos + 10])
        pos = m.end()
        if m.group("num") is not None:
            out.append(("num", int(m.group("num"))))
        elif m.group("str") is not None:
            out.append(("str", m.group("str")[1:-1].replace("''", "'")))
        elif m.group("id") is not None:
            out.append(("id", m.group("id")))
        else:
            out.append(("op", m.group("op")))
    out.append(("eof", None))
    return out


def num(v):
    if isinstance(v, int):
        return v
    m = re.match(r"\s*[-+]?\d+", v)
    return int(m.group()) if m else 0


def text(v):
    return v if isinstance(v, str) else str(v)


def sortkey(v):
    return (1, v) if isinstance(v, str) else (0, v)


def truth(v):
    if v is None:
        return None
    return 1 if num(v) != 0 else 0


def like(s, p):
    rx = "".join(".*" if c == "%" else "." if c == "_" else re.escape(c) for c in p)
    return re.fullmatch(rx, s, re.S | re.I) is not None


class Parser:
    def __init__(self, sql):
        self.t = tokenize(sql)
        self.i = 0

    def peek(self):
        return self.t[self.i]

    def next(self):
        tok = self.t[self.i]
        self.i += 1
        return tok

    def kw(self, *words):
        k, v = self.peek()
        if k == "id" and v.upper() in words:
            return v.upper()
        return None

    def accept_kw(self, w):
        if self.kw(w):
            self.i += 1
            return True
        return False

    def expect_kw(self, w):
        if not self.accept_kw(w):
            raise ValueError("expected " + w)

    def op(self, *ops):
        k, v = self.peek()
        return v if k == "op" and v in ops else None

    def expect_op(self, o):
        if not self.op(o):
            raise ValueError("expected " + o)
        self.i += 1

    def parse_select(self):
        self.expect_kw("SELECT")
        items = []
        while True:
            e = self.expr()
            if self.accept_kw("AS"):
                self.next()
            elif self.peek()[0] == "id" and not self.kw("FROM"):
                self.next()
            items.append(e)
            if self.op(","):
                self.i += 1
            else:
                break
        if self.op(";"):
            self.i += 1
        if self.peek()[0] != "eof":
            raise ValueError("unexpected trailing input")
        return items

    def expr(self):
        return self.or_()

    def or_(self):
        l = self.and_()
        while self.accept_kw("OR"):
            l = ("or", l, self.and_())
        return l

    def and_(self):
        l = self.not_()
        while self.accept_kw("AND"):
            l = ("and", l, self.not_())
        return l

    def not_(self):
        if self.accept_kw("NOT"):
            return ("not", self.not_())
        return self.cmp()

    def cmp(self):
        l = self.add()
        while True:
            o = self.op("=", "==", "!=", "<>", "<", "<=", ">", ">=")
            if o:
                self.i += 1
                l = ("cmp", {"==": "=", "<>": "!="}.get(o, o), l, self.add())
                continue
            if self.accept_kw("IS"):
                neg = self.accept_kw("NOT")
                self.expect_kw("NULL")
                l = ("isnull", l, neg)
