    if a is None or b is None:
        return None
    a, b = sortkey(a), sortkey(b)
    return int({"=": a == b, "!=": a != b, "<": a < b, "<=": a <= b,
                ">": a > b, ">=": a >= b}[op])


def substr(s, start, length=None):
    s = text(s)
    n = len(s)
    if length is None:
        lo, hi = start, n + 1
        if start < 0:
            lo = max(n + start + 1, 1)
        lo = max(lo, 1)
        return s[lo - 1:hi - 1]
    if start < 0:
        start = n + start + 1
    if length < 0:
        hi = start
        lo = start + length
    else:
        lo, hi = start, start + length
    lo = max(lo, 1)
    hi = min(hi, n + 1)
    return s[lo - 1:hi - 1] if hi > lo else ""


def ev(e):
    t = e[0]
    if t == "lit":
        return e[1]
    if t == "neg":
        v = ev(e[1])
        return None if v is None else -num(v)
    if t == "arith":
        a, b = ev(e[2]), ev(e[3])
        if a is None or b is None:
            return None
        a, b, o = num(a), num(b), e[1]
        if o == "+":
            return a + b
        if o == "-":
            return a - b
        if o == "*":
            return a * b
        if b == 0:
            return None
        q = abs(a) // abs(b)
        if o == "/":
            return q if (a < 0) == (b < 0) else -q
        r = abs(a) % abs(b)
        return -r if a < 0 else r
    if t == "concat":
        a, b = ev(e[1]), ev(e[2])
        return None if a is None or b is None else text(a) + text(b)
    if t == "cmp":
        return compare(e[1], ev(e[2]), ev(e[3]))
    if t == "and":
        a = truth(ev(e[1]))
        if a == 0:
            return 0
        b = truth(ev(e[2]))
        if b == 0:
            return 0
        return None if a is None or b is None else 1
    if t == "or":
        a = truth(ev(e[1]))
        if a == 1:
            return 1
        b = truth(ev(e[2]))
        if b == 1:
            return 1
        return None if a is None or b is None else 0
    if t == "not":
        v = truth(ev(e[1]))
        return None if v is None else 1 - v
    if t == "isnull":
        r = int(ev(e[1]) is None)
        return 1 - r if e[2] else r
    if t == "in":
        x = ev(e[1])
        if x is None:
            return None
        seen_null = False
        for it in e[2]:
            v = ev(it)
            if v is None:
                seen_null = True
            elif compare("=", x, v):
                return 1
        return None if seen_null else 0
    if t == "like":
        a, p = ev(e[1]), ev(e[2])
        if a is None or p is None:
            return None
        return int(like(text(a), text(p)))
    if t == "case":
        _, base, whens, els = e
        bv = ev(base) if base is not None else None
        for c, v in whens:
            if base is None:
                if truth(ev(c)) == 1:
                    return ev(v)
            elif compare("=", bv, ev(c)):
                return ev(v)
        return ev(els) if els is not None else None
    if t == "func":
        return func(e[1], e[2])
    raise ValueError("bad expression")


def func(name, argexprs):
    if name == "COALESCE":
        for a in argexprs:
            v = ev(a)
            if v is not None:
                return v
        return None
    args = [ev(a) for a in argexprs]
    if name == "NULLIF":
        return None if compare("=", args[0], args[1]) else args[0]
    if not args or args[0] is None:
        if name in ("UPPER", "LOWER", "LENGTH", "ABS", "SUBSTR"):
            return None
    if name == "UPPER":
        return text(args[0]).upper()
    if name == "LOWER":
        return text(args[0]).lower()
    if name == "LENGTH":
        return len(text(args[0]))
    if name == "ABS":
        return abs(num(args[0]))
    if name == "SUBSTR":
        if any(a is None for a in args[1:]):
            return None
        return substr(args[0], num(args[1]), num(args[2]) if len(args) > 2 else None)
    raise ValueError("no such function: " + name)


class Database:
    def __init__(self, tables):
        self.tables = tables

    def query(self, sql):
        items = Parser(sql).parse_select()
        return [tuple(ev(e) for e in items)]
