class AtomMixin:
    def add(self):
        l = self.mul()
        while self.op("+", "-"):
            o = self.next()[1]
            l = ("arith", o, l, self.mul())
        return l

    def mul(self):
        l = self.concat()
        while self.op("*", "/", "%"):
            o = self.next()[1]
            l = ("arith", o, l, self.concat())
        return l

    def concat(self):
        l = self.unary()
        while self.op("||"):
            self.i += 1
            l = ("concat", l, self.unary())
        return l

    def unary(self):
        if self.op("-"):
            self.i += 1
            return ("neg", self.unary())
        if self.op("+"):
            self.i += 1
            return self.unary()
        return self.primary()

    def primary(self):
        k, v = self.next()
        if k in ("num", "str"):
            return ("lit", v)
        if k == "op" and v == "(":
            e = self.expr()
            self.expect_op(")")
            return e
        if k == "id":
            u = v.upper()
            if u == "NULL":
                return ("lit", None)
            if u == "CASE":
                return self.case()
            if self.op("("):
                self.i += 1
                args = self.exprlist(")")
                self.expect_op(")")
                return ("func", u, args)
        raise ValueError("syntax error near %r" % (v,))

    def case(self):
        base = None if self.kw("WHEN") else self.expr()
        whens = []
        while self.accept_kw("WHEN"):
            c = self.expr()
            self.expect_kw("THEN")
            whens.append((c, self.expr()))
