STOP = ("FROM", "WHERE", "ORDER", "LIMIT", "OFFSET", "GROUP", "HAVING")


class SelectParser(Parser):
    def exprlist(self, close=None):
        items = []
        if close and self.op(close):
            return items
        while True:
            items.append(self.expr())
            if not self.op(","):
                return items
            self.i += 1

    def item(self):
        if self.op("*"):
            self.i += 1
            return ("star", None), None
        k, v = self.peek()
        n = self.t[self.i + 1:self.i + 4]
        if k == "id" and n[0] == ("op", ".") and n[1] == ("op", "*"):
            self.i += 3
            return ("star", v), None
        e = self.expr()
        alias = None
        if self.accept_kw("AS"):
            alias = self.next()[1]
        elif self.peek()[0] == "id" and not self.kw(*STOP):
            alias = self.next()[1]
        return e, alias

    def parse_select(self):
        self.expect_kw("SELECT")
        q = {"distinct": self.accept_kw("DISTINCT"), "items": [],
             "table": None, "where": None, "order": [], "limit": None,
             "offset": None}
        while True:
            q["items"].append(self.item())
            if not self.op(","):
                break
            self.i += 1
        self.clauses(q)
        if self.op(";"):
            self.i += 1
        if self.peek()[0] != "eof":
            raise ValueError("unexpected trailing input")
        return q
