END = ("WHERE", "ORDER", "LIMIT", "OFFSET", "GROUP", "HAVING")


class ClauseMixin:
    def clauses(self, q):
        if self.accept_kw("FROM"):
            name = self.next()[1]
            alias = None
            if self.accept_kw("AS"):
                alias = self.next()[1]
            elif self.peek()[0] == "id" and not self.kw(*END):
                alias = self.next()[1]
            q["table"] = (name, alias or name)
        if self.accept_kw("WHERE"):
            q["where"] = self.expr()
        if self.accept_kw("ORDER"):
            self.expect_kw("BY")
            while True:
                e = self.expr()
                desc = bool(self.accept_kw("DESC"))
                if not desc:
                    self.accept_kw("ASC")
                q["order"].append((e, desc))
                if not self.op(","):
                    break
                self.i += 1
        if self.accept_kw("LIMIT"):
            q["limit"] = self.expr()
            if self.accept_kw("OFFSET"):
                q["offset"] = self.expr()
