from .parser import Parser
from .clauses import ClauseMixin, END


class SelectParser(Parser, ClauseMixin):
    def exprlist(self, close=None):
        items = []
        if close and self.op(close):
            return items
        while True:
            items.append(self.expr())
            if not self.op(","):
                return items
            self.i += 1

    def item(self):
        if self.op("*"):
            self.i += 1
            return ("star", None), None
        k, v = self.peek()
        n = self.t[self.i + 1:self.i + 3]
        if k == "id" and n == [("op", "."), ("op", "*")]:
            self.i += 3
            return ("star", v), None
        e = self.expr()
        alias = None
        if self.accept_kw("AS"):
            alias = self.next()[1]
        elif self.peek()[0] == "id" and not self.kw("FROM", *END):
            alias = self.next()[1]
        return e, alias

    def parse_select(self):
        self.expect_kw("SELECT")
        q = {"distinct": self.accept_kw("DISTINCT"), "items": [],
             "table": None, "where": None, "order": [], "limit": None,
             "offset": None}
        while True:
            q["items"].append(self.item())
            if not self.op(","):
                break
            self.i += 1
        self.clauses(q)
        if self.op(";"):
            self.i += 1
        if self.peek()[0] != "eof":
            raise ValueError("unexpected trailing input")
        return q
