from .values import num, sortkey


def aggregate(e, env, ev):
    _, name, arg, distinct = e
    envs = getattr(env, "envs", None)
    if envs is None:
        raise ValueError("misuse of aggregate function " + name)
    if arg is None:
        return len(envs)
    vals = [v for v in (ev(arg, r) for r in envs) if v is not None]
    if distinct:
        vals = list(dict.fromkeys(vals))
    if name == "COUNT":
        return len(vals)
    if not vals:
        return None
    if name == "SUM":
        return sum(num(v) for v in vals)
    pick = min if name == "MIN" else max
    return pick(vals, key=sortkey)
