class FromMixin:
    def table_ref(self):
        name = self.next()[1]
        alias = None
        if self.accept_kw("AS"):
            alias = self.next()[1]
        elif self.peek()[0] == "id" and not self.kw(
                "JOIN", "INNER", "LEFT", "CROSS", *END):
            alias = self.next()[1]
        return name, alias or name

    def from_clause(self):
        base = self.table_ref()
        joins = []
        while True:
            if self.op(","):
                self.i += 1
                joins.append(("cross", self.table_ref(), None))
                continue
            kind = None
            if self.accept_kw("LEFT"):
                self.accept_kw("OUTER")
                kind = "left"
            elif self.accept_kw("CROSS"):
                kind = "cross"
            elif self.accept_kw("INNER"):
                kind = "inner"
            if not self.accept_kw("JOIN"):
                if kind:
                    raise ValueError("expected JOIN")
                return {"base": base, "joins": joins}
            ref = self.table_ref()
            on = self.expr() if self.accept_kw("ON") else None
            joins.append((kind or "inner", ref, on))
