class WindowMixin:
    def window(self, e):
        self.expect_op("(")
        part, order, fr = [], [], None
        if self.accept_kw("PARTITION"):
            self.expect_kw("BY")
            part = self.exprlist()
        if self.accept_kw("ORDER"):
            self.expect_kw("BY")
            while True:
                t = self.expr()
                d = bool(self.accept_kw("DESC"))
                self.accept_kw("ASC")
                order.append((t, d))
                if not self.op(","):
                    break
                self.i += 1
        if self.accept_kw("ROWS"):
            fr = self.frame()
        self.expect_op(")")
        return ("win", e, part, order, fr)

    def frame(self):
        if not self.accept_kw("BETWEEN"):
            return self.bound(), ("cur", 0)
        a = self.bound()
        self.expect_kw("AND")
        return a, self.bound()

    def bound(self):
        if self.accept_kw("CURRENT"):
            self.expect_kw("ROW")
            return "cur", 0
        if self.accept_kw("UNBOUNDED"):
            return ("unb_p" if self.next()[1].upper() == "PRECEDING" else "unb_f"), 0
        n = self.next()[1]
        return ("p" if self.next()[1].upper() == "PRECEDING" else "f"), n
