"""SQL value semantics: conversion, comparison, arithmetic helpers."""
import re

from minisql.lexer import SQLError

_NUM_PREFIX = re.compile(r"\s*[+-]?\d+")


def to_num(v):
    """Numeric value of a non-NULL value, SQLite style (text uses its leading integer)."""
    if isinstance(v, bool):
        return int(v)
    if isinstance(v, int):
        return v
    if isinstance(v, str):
        m = _NUM_PREFIX.match(v)
        return int(m.group(0)) if m else 0
    raise SQLError(f"unsupported value {v!r}")


def to_text(v):
    if isinstance(v, str):
        return v
    return str(to_num(v))


def truth(v):
    """Three-valued truth: True, False or None (NULL)."""
    if v is None:
        return None
    return to_num(v) != 0


def compare(a, b):
    """Return -1, 0 or 1 for non-NULL a and b. Numbers sort before text."""
    a_text = isinstance(a, str)
    b_text = isinstance(b, str)
    if a_text != b_text:
        return 1 if a_text else -1
    if a_text:
        return (a > b) - (a < b)
    return (a > b) - (a < b)


def int_div(a, b):
    q = abs(a) // abs(b)
    return q if (a >= 0) == (b >= 0) else -q


def int_mod(a, b):
    r = abs(a) % abs(b)
    return r if a >= 0 else -r
