"""Recursive-descent parser: tokens -> expression AST (nested tuples)."""
from minisql.lexer import SQLError, tokenize

FUNCS = {"UPPER": 1, "LOWER": 1, "LENGTH": 1, "ABS": 1, "SUBSTR": (2, 3),
         "COALESCE": "*", "NULLIF": 2}
CMP_OPS = {"=", "!=", "<>", "<", "<=", ">", ">="}


class Parser:
    def __init__(self, sql):
        self.toks = tokenize(sql)
        self.i = 0

    def peek(self, k=0):
        return self.toks[min(self.i + k, len(self.toks) - 1)]

    def next(self):
        t = self.toks[self.i]
        self.i += 1
        return t

    def is_kw(self, *words):
        t = self.peek()
        return t.kind == "kw" and t.value in words

    def is_op(self, *ops):
        t = self.peek()
        return t.kind == "op" and t.value in ops

    def expect_kw(self, word):
        if not self.is_kw(word):
            raise SQLError(f"expected {word}, got {self.peek().value!r}")
        self.next()

    def expect_op(self, op):
        if not self.is_op(op):
            raise SQLError(f"expected {op!r}, got {self.peek().value!r}")
        self.next()

    # select list
    def parse_select(self):
        self.expect_kw("SELECT")
        items = []
        while True:
            expr = self.parse_expr()
            alias = None
            if self.is_kw("AS"):
                self.next()
                alias = self.parse_alias()
            elif self.peek().kind == "ident":
                alias = self.parse_alias()
            items.append((expr, alias))
            if self.is_op(","):
                self.next()
                continue
            break
        if self.is_op(";"):
            self.next()
        if self.peek().kind != "eof":
            raise SQLError(f"unexpected {self.peek().value!r}")
        return items

    def parse_alias(self):
        t = self.next()
        if t.kind != "ident":
            raise SQLError(f"bad alias {t.value!r}")
        return t.value

    # expressions, lowest precedence first
    def parse_expr(self):
        return self.parse_or()

    def parse_or(self):
        left = self.parse_and()
        while self.is_kw("OR"):
            self.next()
            left = ("or", left, self.parse_and())
        return left

    def parse_and(self):
        left = self.parse_not()
        while self.is_kw("AND"):
            self.next()
            left = ("and", left, self.parse_not())
        return left

    def parse_not(self):
        if self.is_kw("NOT"):
            self.next()
            return ("not", self.parse_not())
        return self.parse_predicate()

    def parse_predicate(self):
        left = self.parse_additive()
        while True:
            if self.is_op(*CMP_OPS):
                op = self.next().value
                op = "!=" if op == "<>" else op
                left = ("cmp", op, left, self.parse_additive())
            elif self.is_kw("IS"):
                self.next()
                neg = False
                if self.is_kw("NOT"):
                    self.next()
                    neg = True
                if self.is_kw("NULL"):
                    self.next()
                    left = ("isnull", left, neg)
                else:
                    raise SQLError("IS must be followed by [NOT] NULL")
            else:
                neg = False
                if self.is_kw("NOT") and self.peek(1).kind == "kw" and \
                        self.peek(1).value in ("IN", "LIKE", "BETWEEN"):
                    self.next()
                    neg = True
                if self.is_kw("BETWEEN"):
                    self.next()
                    lo = self.parse_additive()
                    self.expect_kw("AND")
                    hi = self.parse_additive()
                    left = ("between", left, lo, hi, neg)
                elif self.is_kw("IN"):
                    self.next()
                    self.expect_op("(")
                    items = [self.parse_expr()]
                    while self.is_op(","):
                        self.next()
                        items.append(self.parse_expr())
                    self.expect_op(")")
                    left = ("in", left, items, neg)
                elif self.is_kw("LIKE"):
                    self.next()
                    left = ("like", left, self.parse_additive(), neg)
                elif neg:
                    raise SQLError("expected IN, LIKE or BETWEEN after NOT")
                else:
                    return left

    def parse_additive(self):
        left = self.parse_multiplicative()
        while self.is_op("+", "-"):
            op = self.next().value
            left = ("bin", op, left, self.parse_multiplicative())
        return left

    def parse_multiplicative(self):
        left = self.parse_concat()
        while self.is_op("*", "/", "%"):
            op = self.next().value
            left = ("bin", op, left, self.parse_concat())
        return left

    def parse_concat(self):
        left = self.parse_unary()
        while self.is_op("||"):
            self.next()
            left = ("concat", left, self.parse_unary())
        return left

    def parse_unary(self):
        if self.is_op("-"):
            self.next()
            return ("neg", self.parse_unary())
        if self.is_op("+"):
            self.next()
            return self.parse_unary()
        return self.parse_primary()

    def parse_primary(self):
        t = self.peek()
        if t.kind == "num":
            self.next()
            return ("lit", t.value)
        if t.kind == "str":
            self.next()
            return ("lit", t.value)
        if t.kind == "kw" and t.value == "NULL":
            self.next()
            return ("lit", None)
        if t.kind == "kw" and t.value == "CASE":
            return self.parse_case()
        if self.is_op("("):
            self.next()
            e = self.parse_expr()
            self.expect_op(")")
            return e
        if t.kind == "ident":
            self.next()
            if not self.is_op("("):
                raise SQLError(f"no such column: {t.value}")
            return self.parse_call(t.value)
        raise SQLError(f"unexpected {t.value!r}")

    def parse_call(self, name):
        self.expect_op("(")
        args = []
        if not self.is_op(")"):
            args.append(self.parse_expr())
            while self.is_op(","):
                self.next()
                args.append(self.parse_expr())
        self.expect_op(")")
        up = name.upper()
        if up not in FUNCS:
            raise SQLError(f"no such function: {name}")
        arity = FUNCS[up]
        ok = (arity == "*" and args) or (
            isinstance(arity, tuple) and len(args) in arity) or (
            isinstance(arity, int) and len(args) == arity)
        if not ok:
            raise SQLError(f"wrong number of arguments to {up}")
        return ("func", up, args)

    def parse_case(self):
        self.expect_kw("CASE")
        operand = None
        if not self.is_kw("WHEN"):
            operand = self.parse_expr()
        whens = []
        while self.is_kw("WHEN"):
            self.next()
            cond = self.parse_expr()
            self.expect_kw("THEN")
            whens.append((cond, self.parse_expr()))
        if not whens:
            raise SQLError("CASE needs WHEN")
        else_ = None
        if self.is_kw("ELSE"):
            self.next()
            else_ = self.parse_expr()
        self.expect_kw("END")
        return ("case", operand, whens, else_)


def parse_select(sql):
    return Parser(sql).parse_select()
