    """rows: list of (out, keys) pairs; stable sort on keys."""
    def cmp(x, y):
        for i, desc in enumerate(desc_flags):
            c = _cmp_val(x[1][i], y[1][i])
            if c:
                return -c if desc else c
        return 0
