"""Runs a parsed SELECT against the tables of a Database."""
from functools import cmp_to_key

from minisql.evaluator import evaluate
from minisql.lexer import SQLError
from minisql.parser import parse_select
from minisql.values import compare, truth


class Ctx:
    """Row context: resolves column references for one row."""

    def __init__(self, scope, row):
        self.scope = scope  # (quals, columns) or None when there is no FROM
        self.row = row

    def col(self, qual, name):
        if self.scope is None:
            raise SQLError(f"no such column: {name}")
        quals, cols = self.scope
        if qual is not None and qual.lower() not in quals:
            raise SQLError(f"no such column: {qual}.{name}")
        hits = [i for i, c in enumerate(cols) if c == name.lower()]
        if not hits:
            raise SQLError(f"no such column: {name}")
        return self.row[hits[0]]


def _find_table(tables, name):
    for key, val in tables.items():
        if key.lower() == name.lower():
            return val
    raise SQLError(f"no such table: {name}")


def _cmp_val(a, b):
    if a is None or b is None:
        return (a is not None) - (b is not None)
    return compare(a, b)


def _run_order(rows, order):
    """rows: list of (out, keys). order: list of desc flags."""
    def cmp(x, y):
        for i, desc in enumerate(order):
            c = _cmp_val(x[1][i], y[1][i])
            if c:
                return -c if desc else c
        return 0
    return sorted(rows, key=cmp_to_key(cmp))
