        _key, (cols, data) = _find_table(tables, name)
        scope = ({(alias or name).lower()}, [c.lower() for c in cols])
    items, order = sel["items"], sel["order"]
    names = {it[2].lower(): i for i, it in enumerate(items) if it[0] == "expr" and it[2]}
