from .values import truth, compare, to_text, to_num, like
from .functions import call

CMPS = {"=": lambda c: c == 0, "!=": lambda c: c != 0, "<>": lambda c: c != 0,
        "<": lambda c: c < 0, "<=": lambda c: c <= 0, ">": lambda c: c > 0,
        ">=": lambda c: c >= 0}


def arith(op, a, b):
    if a is None or b is None:
        return None
    a, b = to_num(a), to_num(b)
    if op == "+":
        return a + b
    if op == "-":
        return a - b
    if op == "*":
        return a * b
    if b == 0:
        return None
    if op == "/":
        q = abs(a) // abs(b)
        return q if (a < 0) == (b < 0) else -q
    r = abs(a) % abs(b)
    return -r if a < 0 else r


def logic_and(a, b):
    if a == 0 or b == 0:
        return 0
    return None if a is None or b is None else 1


def logic_or(a, b):
    if a == 1 or b == 1:
        return 1
    return None if a is None or b is None else 0


def neg_if(r, neg):
    return r if r is None or not neg else 1 - r


def ev_in(n):
    x = ev(n[1])
    if x is None:
        return None
    r = 0
    for it in n[2]:
        v = ev(it)
        if v is None:
            r = None if r == 0 else r
        elif compare(x, v) == 0:
            r = 1
            break
    return neg_if(r, n[3])


def ev_case(n):
    b = ev(n[1]) if n[1] is not None else None
    for c, v in n[2]:
        w = ev(c)
        if n[1] is None:
            ok = truth(w) == 1
        else:
            ok = b is not None and w is not None and compare(b, w) == 0
        if ok:
            return ev(v)
    return ev(n[3]) if n[3] is not None else None
