    if n[1] == "COALESCE":
        for a in n[2]:
            v = ev(a)
            if v is not None:
                return v
        return None
    return call(n[1], [ev(a) for a in n[2]])


def ev_cmp(n):
    a, b = ev(n[2]), ev(n[3])
    if a is None or b is None:
