from .values import to_num
from .evaluator import ev
from .sorting import sort_rows


def uniq(rows):
    return list(dict.fromkeys(rows))


def combine(op, rows, rr):
    if op == "UNION ALL":
        return rows + rr
    if op == "UNION":
        return uniq(rows + rr)
    s = set(rr)
    return uniq([x for x in rows if (x in s) == (op == "INTERSECT")])


def run_compound(tables, q, outer):
    from .run import run_full
    names, rows = run_full(tables, q["first"], outer)
    for op, r in q["ops"]:
        rows = combine(op, rows, run_full(tables, r, outer)[1])
    if q["order"]:
        pairs = [({n.lower(): v for n, v in zip(names, row)}, row) for row in rows]
        rows = sort_rows(pairs, q["order"], [(None, n) for n in names])
    if q["limit"] is not None:
        off = to_num(ev(q["offset"], None)) if q["offset"] is not None else 0
        lim = to_num(ev(q["limit"], None))
        rows = rows[off:] if lim < 0 else rows[off:off + lim]
    return names, rows


def run_recursive(tables, name, cols, cq, outer):
    from .run import run_full
    op, step = cq["ops"][0]
    names, base = run_full(tables, cq["first"], outer)
    cols = cols or names
    allrows = uniq(base) if op == "UNION" else list(base)
    seen, work = set(allrows), list(allrows)
    while work:
        t = dict(tables)
        t[name] = (cols, work)
        new = run_full(t, step, outer)[1]
        if op == "UNION":
            new = [r for r in uniq(new) if r not in seen]
            seen.update(new)
        allrows += new
        work = new
    return cols, allrows
