class WinMixin:
    def bound(self):
        if self.accept_kw("UNBOUNDED"):
            self.next()
            return None
        if self.accept_kw("CURRENT"):
            self.next()
            return 0
        n = self.next()[1]
        return -n if self.next()[1].upper() == "PRECEDING" else n

    def over(self, node):
        if not self.accept_kw("OVER"):
            return node
        self.expect_op("(")
        part, order, frame = [], [], None
        if self.accept_kw("PARTITION"):
            self.expect_kw("BY")
            part = [self.expr()]
            while self.accept_op(","):
                part.append(self.expr())
        if self.accept_kw("ORDER"):
            self.expect_kw("BY")
            while True:
                e = self.expr()
                desc = bool(self.accept_kw("DESC"))
                self.accept_kw("ASC")
                order.append((e, desc))
                if not self.accept_op(","):
                    break
        if self.accept_kw("ROWS"):
            if self.accept_kw("BETWEEN"):
                s = self.bound()
                self.expect_kw("AND")
                frame = (s, self.bound())
            else:
                frame = (self.bound(), 0)
        self.expect_op(")")
        return ("win", node, part, order, frame)
