from functools import cmp_to_key
from .evaluator import ev
from .agg import ev_agg
from .engine import cmp_null


def find(n, out):
    if isinstance(n, tuple) and n and n[0] == "win":
        out.append(n)
    elif isinstance(n, (tuple, list)):
        for x in n:
            find(x, out)


def apply_windows(envs, items, order):
    wins = []
    find([e for e, _ in items], wins)
    find(order, wins)
    for w in wins:
        compute(w, envs)


def compute(w, envs):
    _, f, part, order, frame = w
    groups = {}
    for i, e in enumerate(envs):
        groups.setdefault(tuple(ev(p, e) for p in part), []).append(i)
    for idx in groups.values():
        keys = {i: [ev(o, envs[i]) for o, _ in order] for i in idx}

        def cmp(a, b):
            for (_, d), x, y in zip(order, keys[a], keys[b]):
                c = cmp_null(x, y)
                if c:
                    return -c if d else c
            return 0
        idx.sort(key=cmp_to_key(cmp))
        for pos, i in enumerate(idx):
            envs[i][("w", id(w))] = value(f, envs, idx, pos, bool(order), frame, cmp)


def ranking(name, args, envs, idx, pos, peers, cmp):
    n, me = len(idx), idx[pos]
    if name == "ROW_NUMBER":
        return pos + 1
    if name == "RANK":
        return peers[0] + 1
    if name == "DENSE_RANK":
        return 1 + sum(1 for p in range(1, peers[0] + 1) if cmp(idx[p - 1], idx[p]) != 0)
    k = ev(args[0], envs[me])
    base, extra = divmod(n, k)
    big = extra * (base + 1)
    return pos // (base + 1) + 1 if pos < big else extra + (pos - big) // base + 1
