TOKEN_RE = re.compile(r"""\s*(?:(?P<num>\d+)|(?P<str>'(?:[^']|'')*')|(?P<id>[A-Za-z_][A-Za-z_0-9]*)|(?P<op>\|\||<>|!=|<=|>=|[-+*/%=<>(),;.]))""")


def tokenize(sql):
    toks = []
    pos = 0
    sql = sql.rstrip()
    while pos < len(sql):
        m = TOKEN_RE.match(sql, pos)
        if not m:
            raise SQLError("bad token at %d" % pos)
        pos = m.end()
        if m.group("num") is not None:
            toks.append(("num", int(m.group("num"))))
        elif m.group("str") is not None:
            toks.append(("str", m.group("str")[1:-1].replace("''", "'")))
        elif m.group("id") is not None:
            toks.append(("id", m.group("id")))
        else:
            toks.append(("op", m.group("op")))
    toks.append(("eof", None))
    return toks


def truth(v):
    if v is None:
        return None
    if isinstance(v, str):
        m = re.match(r"\s*[-+]?\d+", v)
        return 1 if m and int(m.group().strip()) != 0 else 0
    return 1 if v != 0 else 0


def _rank(v):
    return 1 if isinstance(v, int) else 2


def compare(a, b):
    ra, rb = _rank(a), _rank(b)
    if ra != rb:
        return -1 if ra < rb else 1
    return (a > b) - (a < b)


def to_text(v):
    return v if isinstance(v, str) else str(v)


def to_num(v):
    if isinstance(v, int):
        return v
    m = re.match(r"\s*[-+]?\d+", v)
    return int(m.group()) if m else 0


def like(s, pat):
    rx = "".join(".*" if c == "%" else "." if c == "_" else re.escape(c) for c in pat)
    return re.fullmatch(rx, s, re.I | re.S) is not None


KEYWORDS = {"AND", "OR", "NOT", "IS", "IN", "BETWEEN", "LIKE", "CASE", "WHEN", "THEN",
            "ELSE", "END", "NULL", "AS", "FROM", "WHERE"}


class Parser:
    def __init__(self, toks):
        self.t = toks
        self.i = 0

    def peek(self):
        return self.t[self.i]

    def next(self):
        tok = self.t[self.i]
        self.i += 1
        return tok

    def kw(self, *words):
        k, v = self.peek()
        if k == "id" and v.upper() in words:
            return v.upper()
        return None

    def accept_kw(self, w):
        if self.kw(w):
            self.i += 1
            return True
        return False

    def expect_kw(self, w):
        if not self.accept_kw(w):
            raise SQLError("expected " + w)

    def accept_op(self, o):
        if self.peek() == ("op", o):
            self.i += 1
            return True
        return False

    def expect_op(self, o):
        if not self.accept_op(o):
            raise SQLError("expected " + o)

    def parse_select(self):
        self.expect_kw("SELECT")
        items = []
        while True:
            e = self.expr()
            name = None
            if self.accept_kw("AS"):
                name = self.next()[1]
            elif self.peek()[0] == "id" and not self.kw(*KEYWORDS):
                name = self.next()[1]
            items.append((e, name))
            if not self.accept_op(","):
                break
        self.accept_op(";")
        if self.peek()[0] != "eof":
            raise SQLError("unexpected token %r" % (self.peek(),))
        return items

    def expr(self):
        return self.or_()

    def or_(self):
        l = self.and_()
        while self.accept_kw("OR"):
            l = ("or", l, self.and_())
        return l

    def and_(self):
        l = self.not_()
        while self.accept_kw("AND"):
            l = ("and", l, self.not_())
        return l

    def not_(self):
        if self.accept_kw("NOT"):
            return ("not", self.not_())
        return self.cmp()

    def cmp(self):
        l = self.add()
        while True:
            k, v = self.peek()
            if k == "op" and v in ("=", "!=", "<>", "<", "<=", ">", ">="):
                self.i += 1
                l = ("cmp", v, l, self.add())
                continue
            if self.accept_kw("IS"):
                neg = self.accept_kw("NOT")
                self.expect_kw("NULL")
                l = ("isnull", l, neg)
                continue
            neg = False
            save = self.i
            if self.kw("NOT"):
                self.i += 1
                neg = True
                if not self.kw("IN", "LIKE", "BETWEEN"):
                    self.i = save
                    return l
            if self.accept_kw("IN"):
                self.expect_op("(")
                items = [self.expr()]
                while self.accept_op(","):
                    items.append(self.expr())
                self.expect_op(")")
                l = ("in", l, items, neg)
            elif self.accept_kw("LIKE"):
                l = ("like", l, self.add(), neg)
            elif self.accept_kw("BETWEEN"):
                lo = self.add()
                self.expect_kw("AND")
                hi = self.add()
                l = ("between", l, lo, hi, neg)
            else:
                return l

    def add(self):
        l = self.mul()
        while self.peek() in (("op", "+"), ("op", "-")):
            op = self.next()[1]
            l = ("arith", op, l, self.mul())
        return l

    def mul(self):
        l = self.concat()
        while self.peek() in (("op", "*"), ("op", "/"), ("op", "%")):
            op = self.next()[1]
            l = ("arith", op, l, self.concat())
        return l

    def concat(self):
        l = self.unary()
        while self.accept_op("||"):
            l = ("concat", l, self.unary())
        return l

    def unary(self):
        if self.accept_op("-"):
            return ("neg", self.unary())
        if self.accept_op("+"):
            return self.unary()
        return self.primary()

    def primary(self):
        k, v = self.next()
        if k in ("num", "str"):
            return ("lit", v)
        if k == "op" and v == "(":
            e = self.expr()
            self.expect_op(")")
            return e
        if k == "id":
            u = v.upper()
            if u == "NULL":
                return ("lit", None)
            if u == "CASE":
                return self.case()
            if self.accept_op("("):
                args = []
                if not self.accept_op(")"):
                    args.append(self.expr())
                    while self.accept_op(","):
                        args.append(self.expr())
                    self.expect_op(")")
                return ("func", u, args)
        raise SQLError("unexpected token %r" % ((k, v),))

    def case(self):
        base = None
        if not self.kw("WHEN"):
            base = self.expr()
        whens = []
        while self.accept_kw("WHEN"):
            c = self.expr()
            self.expect_kw("THEN")
            whens.append((c, self.expr()))
        els = None
        if self.accept_kw("ELSE"):
            els = self.expr()
        self.expect_kw("END")
        return ("case", base, whens, els)


def ev(n):
    t = n[0]
    if t == "lit":
        return n[1]
    if t == "neg":
        v = ev(n[1])
        return None if v is None else -to_num(v)
    if t == "arith":
        a, b = ev(n[2]), ev(n[3])
        if a is None or b is None:
            return None
        a, b = to_num(a), to_num(b)
        op = n[1]
        if op == "+":
            return a + b
        if op == "-":
            return a - b
        if op == "*":
            return a * b
        if b == 0:
            return None
        q = abs(a) // abs(b)
        if op == "/":
            return q if (a < 0) == (b < 0) else -q
        r = abs(a) % abs(b)
        return -r if a < 0 else r
    if t == "concat":
        a, b = ev(n[1]), ev(n[2])
        return None if a is None or b is None else to_text(a) + to_text(b)
    if t == "cmp":
        a, b = ev(n[2]), ev(n[3])
        if a is None or b is None:
            return None
        c = compare(a, b)
        return int({"=": c == 0, "!=": c != 0, "<>": c != 0, "<": c < 0,
                    "<=": c <= 0, ">": c > 0, ">=": c >= 0}[n[1]])
    if t == "and":
        a = truth(ev(n[1]))
        if a == 0:
            return 0
        b = truth(ev(n[2]))
        if b == 0:
            return 0
        return None if a is None or b is None else 1
    if t == "or":
        a = truth(ev(n[1]))
        if a == 1:
            return 1
        b = truth(ev(n[2]))
        if b == 1:
            return 1
        return None if a is None or b is None else 0
    if t == "not":
        a = truth(ev(n[1]))
        return None if a is None else 1 - a
    if t == "isnull":
        r = ev(n[1]) is None
        return int(r != bool(n[2]))
    if t == "between":
        x, lo, hi = ev(n[1]), ev(n[2]), ev(n[3])
        a = None if x is None or lo is None else int(compare(x, lo) >= 0)
        b = None if x is None or hi is None else int(compare(x, hi) <= 0)
        if a == 0 or b == 0:
            r = 0
        elif a is None or b is None:
            r = None
        else:
            r = 1
        return None if r is None else (1 - r if n[4] else r)
    if t == "in":
        x = ev(n[1])
        if x is None:
            return None
        r = 0
        for it in n[2]:
            v = ev(it)
            if v is None:
                r = None if r == 0 else r
            elif compare(x, v) == 0:
                r = 1
                break
        return None if r is None else (1 - r if n[3] else r)
    if t == "like":
        a, p = ev(n[1]), ev(n[2])
        if a is None or p is None:
            return None
        r = int(like(to_text(a), to_text(p)))
        return 1 - r if n[3] else r
    if t == "case":
        if n[1] is None:
            for c, v in n[2]:
                if truth(ev(c)) == 1:
                    return ev(v)
        else:
            b = ev(n[1])
            for c, v in n[2]:
                w = ev(c)
                if b is not None and w is not None and compare(b, w) == 0:
                    return ev(v)
        return ev(n[3]) if n[3] is not None else None
    if t == "func":
        return func(n[1], n[2])
    raise SQLError("bad node")


def func(name, args):
    if name == "COALESCE":
        for a in args:
            v = ev(a)
            if v is not None:
                return v
        return None
    vals = [ev(a) for a in args]
    if name == "NULLIF":
        a, b = vals
        if a is not None and b is not None and compare(a, b) == 0:
            return None
        return a
    if not vals or vals[0] is None:
        return None
    v = vals[0]
    if name == "UPPER":
        return to_text(v).upper()
    if name == "LOWER":
        return to_text(v).lower()
    if name == "LENGTH":
        return len(to_text(v))
    if name == "ABS":
        return abs(to_num(v))
    if name == "SUBSTR":
        s = to_text(v)
        if vals[1] is None:
            return None
        start = to_num(vals[1])
        if len(vals) > 2:
            if vals[2] is None:
                return None
            ln = to_num(vals[2])
            if start > 0:
                b = start - 1
            elif start == 0:
                b, ln = 0, ln - 1
            else:
                b = max(len(s) + start, 0) if False else len(s) + start
            if ln < 0:
                e = max(b, 0)
                b = max(b + ln, 0)
                return s[b:e]
            e = b + ln
            return s[max(b, 0):max(e, 0)]
        if start > 0:
            return s[start - 1:]
        if start == 0:
            return s
        return s[max(len(s) + start, 0):]
    raise SQLError("unknown function " + name)


class Database:
    def __init__(self, tables):
        self.tables = tables

    def query(self, sql):
        items = Parser(tokenize(sql)).parse_select()
        return [tuple(ev(e) for e, _ in items)]
