from .values import compare, to_text, to_num


def substr(vals):
    s = to_text(vals[0])
    if vals[1] is None:
        return None
    start = to_num(vals[1])
    if len(vals) < 3:
        return s[start - 1:] if start > 0 else s[max(len(s) + start, 0):] if start < 0 else s
    if vals[2] is None:
        return None
    ln = to_num(vals[2])
    b = start - 1 if start > 0 else len(s) + start if start < 0 else -1
    if start == 0:
        ln -= 1
        b = 0
    if ln < 0:
        e = max(b, 0)
        return s[max(b + ln, 0):e]
    return s[max(b, 0):max(b + ln, 0)]


def call(name, vals):
    if name == "NULLIF":
        a, b = vals
        return None if a is not None and b is not None and compare(a, b) == 0 else a
    if not vals or vals[0] is None:
        return None
    v = vals[0]
    if name == "UPPER":
        return to_text(v).upper()
    if name == "LOWER":
        return to_text(v).lower()
    if name == "LENGTH":
        return len(to_text(v))
    if name == "ABS":
        return abs(to_num(v))
    if name == "SUBSTR":
        return substr(vals)
    raise ValueError("unknown function " + name)
