from functools import cmp_to_key
from .lexer import SQLError
from .values import truth, compare
from .evaluator import ev


def cmp_null(a, b):
    if a is None or b is None:
        return (a is not None) - (b is not None)
    return compare(a, b)


def make_env(cols, row, alias):
    env = {}
    for c, v in zip(cols, row):
        env[c.lower()] = v
        env[alias.lower() + "." + c.lower()] = v
    return env


def expand_items(items, cols, alias):
    out = []
    for e, name in items:
        if e[0] == "star":
            if e[1] is not None and e[1].lower() != alias.lower():
                raise SQLError("no such table: " + e[1])
            out.extend((("col", None, c), c) for c in cols)
        else:
            out.append((e, name))
    return out


def order_value(term, items, env, out):
    if term[0] == "lit" and isinstance(term[1], int):
        if not 1 <= term[1] <= len(out):
            raise SQLError("bad ORDER BY position")
        return out[term[1] - 1]
    if term[0] == "col" and term[1] is None:
        for i, (e, name) in enumerate(items):
            if name is not None and name.lower() == term[2].lower():
                return out[i]
    return ev(term, env)


def sort_rows(pairs, order, items):
    keyed = [([order_value(t, items, env, out) for t, _ in order], out)
             for env, out in pairs]

    def cmp(x, y):
        for (_, desc), a, b in zip(order, x[0], y[0]):
            c = cmp_null(a, b)
            if c:
                return -c if desc else c
        return 0
    keyed.sort(key=cmp_to_key(cmp))
    return [out for _, out in keyed]
