from .lexer import SQLError
from .values import truth, to_num
from .evaluator import ev
from .engine import make_env, expand_items, sort_rows


def run_select(tables, q):
    if q["table"] is None:
        envs = [None]
        cols, alias = [], ""
    else:
        found = {k.lower(): v for k, v in tables.items()}
        if q["table"].lower() not in found:
            raise SQLError("no such table: " + q["table"])
        cols, rows = found[q["table"].lower()]
        alias = q["alias"] or q["table"]
        envs = [make_env(cols, r, alias) for r in rows]
    if q["where"] is not None:
        envs = [e for e in envs if truth(ev(q["where"], e)) == 1]
    items = expand_items(q["items"], cols, alias)
    pairs = [(e, tuple(ev(x, e) for x, _ in items)) for e in envs]
    if q["distinct"]:
        seen, uniq = set(), []
        for e, out in pairs:
            if out not in seen:
                seen.add(out)
                uniq.append((e, out))
        pairs = uniq
    if q["order"]:
        result = sort_rows(pairs, q["order"], items)
    else:
        result = [out for _, out in pairs]
    if q["limit"] is not None:
        off = to_num(ev(q["offset"], None)) if q["offset"] is not None else 0
        lim = to_num(ev(q["limit"], None))
        result = result[off:] if lim < 0 else result[off:off + lim]
    return result
