        lim = to_num(ev(q["limit"], None))
        rows = rows[off:] if lim < 0 else rows[off:off + lim]
    return names, rows


def run_recursive(tables, name, cols, cq, outer):
    from .run import run_full
    op, step = cq["ops"][0]
    names, base = run_full(tables, cq["first"], outer)
    cols = cols or names
    allrows = uniq(base) if op == "UNION" else list(base)
    seen, work = set(allrows), list(allrows)
    while work:
